  Object.assign(META,{"40": ["وفاتها: قبل الهجرة بنحو 3 سنين", "مكة"], "41": ["استشهاده: 3 هـ", "أُحد"], "42": ["وفاته: 18 هـ", "عمواس بالشام"], "43": ["وفاته: نحو 32 هـ", "الربذة"], "44": ["وفاته: 18 هـ", "عمواس بالشام"], "45": ["وفاته: نحو 55 هـ", "قرب المدينة"], "46": ["وفاته: نحو 57 هـ", "المدينة المنورة"], "47": ["وفاتها: 73 هـ", "مكة"], "48": ["السنة 5 هـ", "المدينة المنورة"], "49": ["السنة 7 هـ", "مكة"], "50": ["السنة 11 هـ", "المدينة المنورة"], "51": ["من أخلاقه ﷺ", "المدينة المنورة"], "52": ["من أخلاقه ﷺ", "المدينة المنورة"]});
  const NEWS5=[{"id": 60, "ch": 9, "t": "آدم عليه السلام", "s": "أول البشر وأول الأنبياء.", "p": ["خلق الله آدم من طين وسوّاه ونفخ فيه من روحه، وأمر الملائكة بالسجود له، وهو سجود تحية وإكرام. فسجدوا كلهم إلا إبليس، أبى واستكبر وقال إنه خير منه لأنه خُلق من نار، فطرده الله من رحمته.", "وعلّم الله آدم الأسماء كلها، ثم عرضهم على الملائكة فقالوا: سبحانك لا علم لنا إلا ما علّمتنا. فظهر فضل العلم، وكان الإنسان خليفة في الأرض يعمّرها.", "وأسكن الله آدم وزوجه الجنة، وأباح لهما كل شيء إلا شجرة واحدة نهاهما عن الاقتراب منها. فوسوس لهما الشيطان وأقسم لهما إنه ناصح، فأكلا منها فبدت لهما سوآتهما.", "فأسرعا إلى التوبة وقالا: «ربنا ظلمنا أنفسنا وإن لم تغفر لنا وترحمنا لنكونن من الخاسرين». فتاب الله عليهما، ثم أهبطهما إلى الأرض لتبدأ حياة الإنسان فيها.", "ثم كان من أبناء آدم قابيل وهابيل، قدّم كلٌّ منهما قربانًا فتقبّل الله من هابيل ولم يتقبل من قابيل، فحسده وقتله. ثم بعث الله غرابًا يبحث في الأرض ليُريه كيف يواري سوءة أخيه، فندم قابيل. وبذلك كان أول موت وأول دفن على الأرض."], "f": ["الحسد والكِبر أصل كثير من الذنوب، والتوبة أصل النجاة.", "العلم هو ما جعل الإنسان خليفة في الأرض."], "qs": [{"q": "لماذا طُرد إبليس من رحمة الله؟", "c": "استكبر ولم يسجد لآدم", "w": ["قتل أخاه", "أكل من الشجرة", "كذب على الملائكة"], "n": "قال أنا خير منه."}, {"t": "tf", "q": "أُمر آدم وزوجه ألا يقتربا من شجرة واحدة فقط.", "c": true, "n": "وأُبيح لهما ما سواها."}, {"t": "fill", "q": "قال آدم وزوجه: ربنا ظلمنا أنفسنا وإن لم تغفر لنا وترحمنا لنكونن من ___.", "c": "الخاسرين", "w": ["الهالكين", "الغافلين", "المعذّبين"], "n": "فقبل الله توبتهما."}, {"q": "ما الذي علّمه الله لآدم وأظهر به فضله على الملائكة؟", "c": "الأسماء كلها", "w": ["الكتابة", "الصناعة", "لغة الطير"], "n": "فعجزت الملائكة عن ذلك."}, {"q": "من الذي علّم قابيل كيف يواري أخاه؟", "c": "غراب يبحث في الأرض", "w": ["جبريل", "هابيل", "آدم"], "n": "فندم قابيل على فعلته."}], "q": {"q": "لماذا طُرد إبليس من رحمة الله؟", "c": "استكبر ولم يسجد لآدم", "w": ["قتل أخاه", "أكل من الشجرة", "كذب على الملائكة"], "n": "قال أنا خير منه."}}, {"id": 61, "ch": 9, "t": "نوح عليه السلام", "s": "صبر ألف سنة إلا خمسين عامًا.", "p": ["كان نوح أول رسول أُرسل إلى أهل الأرض بعد أن انتشر فيهم الشرك. وكان قومه يعبدون أصنامًا ذكر القرآن أسماءها: وَدًّا وسُواعًا ويغوثَ ويعوقَ ونسرًا، وكانت أسماء رجال صالحين مرّ عليهم الزمن حتى عُبدوا.", "ودعا نوح قومه ليلًا ونهارًا، سرًّا وجهرًا، وبقي فيهم ألف سنة إلا خمسين عامًا كما ذكر القرآن، فلم يؤمن معه إلا قليل. وكان كبراؤهم يقولون له: ما نراك إلا بشرًا مثلنا، وما اتبعك إلا أراذلنا.", "فأوحى الله إليه أن يصنع السفينة، وكان قومه يمرّون به ويسخرون منه، فيقول لهم: إن تسخروا منا فإنا نسخر منكم كما تسخرون، وسوف تعلمون.", "فلما جاء أمر الله فار التنور وانهمر الماء من السماء، فحمل نوح في السفينة من كل زوجين اثنين وأهله والمؤمنين. وكان ابنه بعيدًا عنهم فناداه أن يركب معهم، فقال: سآوي إلى جبل يعصمني من الماء. فقال نوح: لا عاصم اليوم من أمر الله إلا من رحم.", "وحال بينهما الموج فكان من المغرَقين. ثم أمر الله الأرض أن تبلع ماءها والسماء أن تُقلع، وانتهى الطوفان، واستوت السفينة على الجُودي. وجعل الله ذرية من نجا هم الباقين."], "f": ["الثبات على الدعوة لا يرتبط بكثرة المستجيبين.", "النسب لا ينفع وحده، والإيمان هو الذي ينجّي."], "qs": [{"q": "كم مكث نوح في قومه يدعوهم؟", "c": "ألف سنة إلا خمسين عامًا", "w": ["مئة سنة", "خمسمئة سنة", "سبعين سنة"], "n": "كما ذكر القرآن."}, {"t": "tf", "q": "ركب ابن نوح السفينة مع أبيه.", "c": false, "n": "فأبى وقال سآوي إلى جبل."}, {"t": "fill", "q": "استوت السفينة على ___.", "c": "الجُودي", "w": ["أحد", "الطور", "حراء"], "n": "بعد انتهاء الطوفان."}, {"t": "match", "q": "صِل كل اسم بما يناسبه:", "pairs": [["وَدّ وسُواع", "أصنام قوم نوح"], ["الجُودي", "مكان استواء السفينة"], ["التنّور", "فار إيذانًا بالطوفان"], ["الأراذل", "وصف كبراء قومه للمؤمنين"]], "n": "من تفاصيل القصة في القرآن."}, {"t": "ord", "q": "رتّب أحداث القصة:", "items": ["دعا قومه ألف سنة إلا خمسين", "صنع السفينة وسخر منه قومه", "فار التنور وبدأ الطوفان", "استوت السفينة على الجودي"], "n": "ثم ابتدأت حياة جديدة للمؤمنين."}], "q": {"q": "كم مكث نوح في قومه يدعوهم؟", "c": "ألف سنة إلا خمسين عامًا", "w": ["مئة سنة", "خمسمئة سنة", "سبعين سنة"], "n": "كما ذكر القرآن."}}, {"id": 62, "ch": 9, "t": "هود عليه السلام", "s": "نبي قوم عاد أصحاب القوة.", "p": ["أرسل الله هودًا إلى قوم عاد، وكانوا يسكنون الأحقاف جنوب الجزيرة العربية، أصحاب أجسام قوية وبنيان عظيم ذكر القرآن «إرم ذات العماد»، وقال إنه لم يُخلق مثلها في البلاد.", "وكانوا بعد قوم نوح، فاستخلفهم الله في الأرض وزادهم في الخلق بسطة، لكنهم بنوا بكل ريع آية يعبثون، واتخذوا مصانع لعلهم يخلدون، وبطشوا بطش الجبارين، وعبدوا الأصنام.", "ودعاهم هود إلى عبادة الله وحده وقال: يا قوم اعبدوا الله ما لكم من إله غيره. فقالوا: ما جئتنا ببينة وما نحن بتاركي آلهتنا، وقالوا إن بعض آلهتنا اعتراك بسوء. فأجابهم بثبات: إني أُشهد الله واشهدوا أني بريء مما تشركون.", "وحين أبطأ عنهم المطر ثم رأوا سحابة قادمة فقالوا: هذا عارض ممطرنا. فقال هود: بل هو ما استعجلتم به، ريح فيها عذاب أليم.", "فأرسل الله عليهم ريحًا صرصرًا عاتية سبع ليال وثمانية أيام حسومًا، فصاروا كأنهم أعجاز نخل خاوية. ونجّى الله هودًا والذين آمنوا معه برحمة منه."], "f": ["القوة المادية لا تحمي من أمر الله.", "الشكر الصحيح أن تُستعمل النعمة في الخير لا في الغرور."], "qs": [{"q": "إلى أي قوم أُرسل هود؟", "c": "عاد", "w": ["ثمود", "مدين", "قوم لوط"], "n": "سكنوا الأحقاف."}, {"t": "tf", "q": "أهلك الله قوم عاد بريح شديدة.", "c": true, "n": "ريح صرصر عاتية."}, {"t": "fill", "q": "أُهلك قوم عاد بريح فيها عذاب ___.", "c": "أليم", "w": ["بعيد", "مؤجَّل", "خفيف"], "n": "سبع ليال وثمانية أيام."}, {"q": "كم دامت الريح التي أهلكتهم؟", "c": "سبع ليال وثمانية أيام", "w": ["يومًا واحدًا", "ثلاثة أيام", "أربعين يومًا"], "n": "حسومًا متتابعة."}, {"q": "ماذا قال قوم عاد حين رأوا السحابة؟", "c": "هذا عارض ممطرنا", "w": ["هذا غيم عابر", "هذا عذاب من السماء", "هذا سحر هود"], "n": "فكانت ريح العذاب."}], "q": {"q": "إلى أي قوم أُرسل هود؟", "c": "عاد", "w": ["ثمود", "مدين", "قوم لوط"], "n": "سكنوا الأحقاف."}}, {"id": 63, "ch": 9, "t": "صالح عليه السلام", "s": "الناقة التي كانت آية لقوم ثمود.", "p": ["أُرسل صالح إلى قوم ثمود، وكانوا يسكنون الحِجر شمال الحجاز، وقد نحتوا الجبال بيوتًا وبنوا القصور في السهول. وقد أعطاهم الله نعمًا كثيرة فكفروا وعبدوا الأصنام.", "فدعاهم صالح إلى عبادة الله وحده، فقالوا: ما أنت إلا بشر مثلنا فأتِ بآية. وتذكر كتب التفسير أنهم طلبوا أن يُخرج لهم ناقة من الصخرة، فاستجاب الله دعاءه وأخرج لهم ناقة عظيمة.", "وقال لهم صالح: هذه ناقة الله لكم آية، لها شِرب ولكم شِرب يوم معلوم، فلا تمسّوها بسوء. فكانت تشرب ماء البئر يومًا وهم يشربون يومًا، وتذكر كتب التفسير أنها كانت تدرّ لبنًا يكفيهم.", "فاشتدّ ذلك على كبرائهم، فتآمر تسعة رهط على قتلها، وعقر الناقة أشقاهم. فقال لهم صالح: تمتعوا في داركم ثلاثة أيام، ذلك وعد غير مكذوب.", "فأخذتهم الصيحة والرجفة فأصبحوا في ديارهم جاثمين. ونجّى الله صالحًا والذين آمنوا. ولما مرّ النبي ﷺ بديارهم في غزوة تبوك أمر أصحابه ألا يدخلوها إلا وهم باكون، خشية أن يصيبهم ما أصابهم."], "f": ["الآيات الحسية لا تنفع من أغلق قلبه.", "الظلم الجماعي يجلب العقوبة الجماعية."], "qs": [{"q": "ما الآية التي أرسلها الله مع صالح؟", "c": "ناقة من الصخرة", "w": ["عصا تنقلب حية", "طوفان", "نار باردة"], "n": "وكان لها شرب يوم معلوم."}, {"t": "tf", "q": "أمر النبي ﷺ أصحابه بالدخول إلى ديار ثمود بحثًا عن الكنوز.", "c": false, "n": "أمرهم ألا يدخلوها إلا باكين."}, {"t": "fill", "q": "هذه ناقة الله لكم ___.", "c": "آية", "w": ["رزق", "غنيمة", "ميراث"], "n": "لها شرب ولكم شرب."}, {"q": "بماذا أُهلك قوم ثمود؟", "c": "الصيحة", "w": ["الريح", "الغرق", "الجراد"], "n": "فأصبحوا جاثمين."}, {"t": "match", "q": "صِل كل قوم بنبيهم:", "pairs": [["عاد", "هود"], ["ثمود", "صالح"], ["مدين", "شعيب"], ["قوم لوط", "لوط"]], "n": "أقوام ذكرها القرآن."}], "q": {"q": "ما الآية التي أرسلها الله مع صالح؟", "c": "ناقة من الصخرة", "w": ["عصا تنقلب حية", "طوفان", "نار باردة"], "n": "وكان لها شرب يوم معلوم."}}, {"id": 64, "ch": 9, "t": "إبراهيم عليه السلام", "s": "خليل الرحمن وأبو الأنبياء.", "p": ["وُلد إبراهيم في قوم يعبدون الأصنام والكواكب، وكان أبوه آزر يصنع الأصنام. فقال لأبيه بأدب: يا أبتِ لم تعبد ما لا يسمع ولا يبصر؟ فهدّده أبوه وطرده، فقال: سلام عليك سأستغفر لك ربي.", "وتأمل في الكواكب والقمر والشمس، فلما رأى كلًّا منها يغيب قال: لا أحب الآفلين، وأعلن: إني وجّهت وجهي للذي فطر السماوات والأرض حنيفًا. ثم كسّر الأصنام إلا كبيرهم ليسألوه، ولما سألوه قال: بل فعله كبيرهم هذا فاسألوهم إن كانوا ينطقون. فعجزوا عن الجواب.", "فجمعوا له الحطب وأشعلوا نارًا عظيمة ورموه فيها، فقال الله: «يا نار كوني بردًا وسلامًا على إبراهيم». فنجّاه الله منها.", "ثم هاجر إلى الشام ومصر، وتزوج هاجر، ورُزق إسماعيل على كبر. وبأمر الله أسكنهما في وادٍ غير ذي زرع عند البيت الحرام، فتركهما وقال: ربنا إني أسكنت من ذريتي بواد غير ذي زرع. فجرى لهما ماء زمزم ببركة الله.", "ولما بلغ إسماعيل السعي معه رأى إبراهيم في المنام أنه يذبحه، ورؤيا الأنبياء وحي، فقال الابن: يا أبتِ افعل ما تُؤمر ستجدني إن شاء الله من الصابرين. فلما أسلما وتلّه للجبين فداه الله بذبح عظيم، وبقي هذا شعيرة في عيد الأضحى.", "ثم رفع إبراهيم وإسماعيل قواعد الكعبة، وقالا: ربنا تقبّل منا إنك أنت السميع العليم. وأمره الله أن يؤذّن في الناس بالحج فجاء الناس رجالًا وعلى كل ضامر."], "f": ["التفكّر في الخلق طريق إلى معرفة الخالق.", "الاستسلام لأمر الله يُثمر الفرج."], "qs": [{"q": "ماذا قال الله للنار التي أُلقي فيها إبراهيم؟", "c": "كوني بردًا وسلامًا", "w": ["انطفئي", "احترقي ببطء", "اخمدي فورًا"], "n": "فنجّاه الله منها."}, {"t": "tf", "q": "كسّر إبراهيم الأصنام كلها بما فيها كبيرها.", "c": false, "n": "كسّرها إلا كبيرهم."}, {"t": "fill", "q": "قال إبراهيم عن الكواكب: لا أحب ___.", "c": "الآفلين", "w": ["الظالمين", "الكاذبين", "الغافلين"], "n": "أي الغائبين المتغيّرين."}, {"t": "match", "q": "صِل كل شخصية بما يناسبها:", "pairs": [["هاجر", "زوجة إبراهيم وأم إسماعيل"], ["آزر", "أبو إبراهيم"], ["إسماعيل", "الذبيح"], ["زمزم", "ماء جرى لهما بمكة"]], "n": "شخصيات وأحداث من قصة إبراهيم."}, {"t": "ord", "q": "رتّب أحداث القصة:", "items": ["نظر في الكواكب وحطّم الأصنام", "أُلقي في النار فنجّاه الله", "أسكن هاجر وإسماعيل بمكة", "رفع قواعد الكعبة مع إسماعيل"], "n": "ثم أُمر بالأذان في الناس بالحج."}], "q": {"q": "ماذا قال الله للنار التي أُلقي فيها إبراهيم؟", "c": "كوني بردًا وسلامًا", "w": ["انطفئي", "احترقي ببطء", "اخمدي فورًا"], "n": "فنجّاه الله منها."}}, {"id": 65, "ch": 9, "t": "لوط عليه السلام", "s": "النبي الذي نهى قومه عن الفاحشة.", "p": ["كان لوط ابن أخي إبراهيم، آمن به وهاجر معه، ثم أرسله الله إلى قوم يسكنون مدينة سدوم وما حولها قرب البحر الميت. وكان قومه يأتون فاحشة لم يسبقهم بها أحد من العالمين، ويقطعون السبيل ويأتون في ناديهم المنكر.", "فنهاهم لوط بحكمة، وقال: أتأتون الذكران من العالمين وتذرون ما خلق لكم ربكم من أزواجكم؟ بل أنتم قوم عادون. فلم يستمعوا، وقالوا: أخرجوا آل لوط من قريتكم إنهم أناس يتطهرون.", "وجاءت الملائكة إلى إبراهيم أولًا فبشّروه بإسحاق، وأخبروه أنهم مرسلون لإهلاك قوم لوط، فجادلهم عن لوط، فقالوا: إنا منجّوه وأهله إلا امرأته. ثم ذهبوا إلى لوط في صورة شبان حسان الوجه.", "فضاق بهم ذرعًا وخاف عليهم من قومه، وجاء قومه يهرعون إليه، فقال: فاتقوا الله ولا تخزون في ضيفي. فأخبره الملائكة أنهم رسل ربه، وأمروه أن يسري بأهله ليلًا ولا يلتفت منهم أحد إلا امرأته.", "فلما جاء الصبح جعل الله عاليها سافلها وأمطر عليهم حجارة من سجّيل. وكانت امرأة لوط ممن هلك، وتذكر كتب التفسير أنها كانت تعين قومها على ضيوفه، فخانته في الدين. ونجّى الله لوطًا وأهله."], "f": ["لا يكفي النسب إلى الصالحين دون الإيمان.", "الصبر على إصلاح المنكر واجب حتى لو قلّ الأنصار."], "qs": [{"q": "من هو لوط بالنسبة لإبراهيم؟", "c": "ابن أخيه", "w": ["ابنه", "أخوه", "صهره"], "n": "آمن به وهاجر معه."}, {"t": "tf", "q": "نجّى الله امرأة لوط معه.", "c": false, "n": "كانت من الهالكين."}, {"t": "fill", "q": "أمطر الله عليهم حجارة من ___.", "c": "سجّيل", "w": ["نار", "ماء", "طين رطب"], "n": "وجعل عاليها سافلها."}, {"q": "ماذا فعلت الملائكة قبل أن تذهب إلى لوط؟", "c": "بشّرت إبراهيم بإسحاق", "w": ["اعتزلت الناس", "أنزلت الطوفان", "هدمت الكعبة"], "n": "وأخبرته بإهلاك قوم لوط."}, {"t": "match", "q": "صِل كل اسم بما يناسبه:", "pairs": [["سدوم", "مدينة قوم لوط"], ["سجّيل", "حجارة العذاب"], ["إسحاق", "بُشّر به إبراهيم"], ["امرأة لوط", "هلكت مع المهلَكين"]], "n": "من تفاصيل القصة."}], "q": {"q": "من هو لوط بالنسبة لإبراهيم؟", "c": "ابن أخيه", "w": ["ابنه", "أخوه", "صهره"], "n": "آمن به وهاجر معه."}}, {"id": 66, "ch": 9, "t": "يوسف عليه السلام", "s": "أحسن القصص.", "p": ["رأى يوسف وهو صغير في المنام أحد عشر كوكبًا والشمس والقمر ساجدين له، فقصّ رؤياه على أبيه يعقوب، فقال له: يا بني لا تقصص رؤياك على إخوتك فيكيدوا لك كيدًا. وكان إخوته يغارون منه لأن أباه يحبه.", "فاتفقوا على أن يُلقوه في الجُبّ، وأخذوه إلى الصحراء بحجة اللعب، ثم جاؤوا أباهم عشاءً يبكون وجاؤوا على قميصه بدم كذب. فقال يعقوب: بل سوّلت لكم أنفسكم أمرًا فصبر جميل. وجاءت قافلة فأخرجوه وباعوه بثمن بخس.", "واشتراه عزيز مصر وقال لامرأته: أكرمي مثواه عسى أن ينفعنا. ولما راودته امرأة العزيز عن نفسه قال: معاذ الله إنه ربي أحسن مثواي، وفرّ إلى الباب، فدخل السجن ظلمًا ومكث فيه بضع سنين وهو يدعو إلى الله ويعبّر الرؤى.", "ورأى الملك سبع بقرات سمان يأكلهن سبع عجاف، فعبّر يوسف الرؤيا بأن سبع سنين تأتي فيها الخيرات ثم سبع شداد، وأشار بالادّخار. فقرّبه الملك وولّاه خزائن الأرض، وقال يوسف: إني حفيظ عليم.", "وجاء إخوته يطلبون الميرة في سنة القحط فعرفهم وهم له منكرون. وبعد حيلة السقاية وردّ البضاعة حتى جاء أخوه بنيامين، كشف لهم الحقيقة: أنا يوسف وهذا أخي. وقال لهم: «لا تثريب عليكم اليوم يغفر الله لكم».", "وعاد البصر إلى أبيه حين ألقوا قميصه على وجهه، وجاء يعقوب وأهله إلى مصر، وخرّوا له سجدًا، فقال: يا أبتِ هذا تأويل رؤياي من قبل قد جعلها ربي حقًّا."], "f": ["العفو عند القدرة من أعلى الأخلاق.", "الصبر والتقوى يُثمران التمكين بعد الابتلاء."], "qs": [{"q": "ماذا قال يوسف لإخوته حين عرفهم؟", "c": "لا تثريب عليكم اليوم", "w": ["لن أغفر لكم", "اذهبوا فلا تعودوا", "أنتم السبب في سجني"], "n": "فعفا عنهم."}, {"t": "tf", "q": "رأى يوسف في صغره أحد عشر كوكبًا والشمس والقمر ساجدين له.", "c": true, "n": "وكانت رؤيا صادقة."}, {"t": "fill", "q": "قال يوسف: ___ الله إنه ربي أحسن مثواي.", "c": "معاذ", "w": ["والله", "سبحان", "لا حول إلا"], "n": "حين راودته امرأة العزيز."}, {"q": "ماذا فعل الملك بعد أن عبّر يوسف رؤياه؟", "c": "ولّاه خزائن الأرض", "w": ["سجنه أكثر", "نفاه من مصر", "قتل إخوته"], "n": "لأنه حفيظ عليم."}, {"t": "ord", "q": "رتّب أحداث القصة:", "items": ["رأى الرؤيا وغار منه إخوته", "أُلقي في الجب وبيع في مصر", "سُجن ثم عبّر رؤيا الملك", "عفا عن إخوته ولقي أباه"], "n": "ثم تحققت الرؤيا."}], "q": {"q": "ماذا قال يوسف لإخوته حين عرفهم؟", "c": "لا تثريب عليكم اليوم", "w": ["لن أغفر لكم", "اذهبوا فلا تعودوا", "أنتم السبب في سجني"], "n": "فعفا عنهم."}}, {"id": 67, "ch": 9, "t": "أيوب عليه السلام", "s": "مضرب المثل في الصبر.", "p": ["أنعم الله على أيوب بالمال والأهل والصحة، فكان شاكرًا صابرًا. وأراد الله أن يظهر صبره، فابتلاه في ماله وأهله وجسده. وقد وصفه الله بأنه «نعم العبد إنه أواب».", "وتذكر كتب التفسير أن مرضه طال سنين، حتى ابتعد عنه أكثر الناس ولم يبقَ معه إلا زوجته تخدمه وتصبر معه. ولم يشتكِ لأحد إلا لله، وكان لسانه رطبًا بذكر الله.", "ثم نادى ربه بأدب عظيم: «أني مسني الضر وأنت أرحم الراحمين». ولم يطلب شيئًا صريحًا، فكانت دعوته مثالًا في الأدب مع الله.", "فقال الله له: اركض برجلك هذا مغتسل بارد وشراب. فضرب الأرض برجله فنبعت عين ماء، فاغتسل منها وشرب فشُفي من مرضه.", "وعوّضه الله بأهله ومثلهم معهم رحمة منه وذكرى للعابدين. وكان قد حلف أن يضرب زوجته لأمر غضب منها كما يذكر المفسرون، فأمره الله أن يأخذ حزمة من الأعواد فيضربها بها ضربة واحدة ليبرّ بيمينه ولا يؤذيها."], "f": ["الدعاء بالأدب والشكوى إلى الله وحده سنّة الأنبياء.", "الصبر الجميل لا شكوى فيه إلا إلى الله."], "qs": [{"q": "ماذا قال أيوب في دعائه؟", "c": "أني مسني الضر وأنت أرحم الراحمين", "w": ["ربّ ارحمني ولا تبتلني", "اللهم اشفني الآن", "ربّ أعطني ما طلب قومي"], "n": "دعاء مليء بالأدب."}, {"t": "tf", "q": "خرج من الأرض ماء بارد لما ضرب أيوب برجله.", "c": true, "n": "فاغتسل منه وشرب وشُفي."}, {"t": "fill", "q": "اركض برجلك هذا ___ بارد وشراب.", "c": "مغتسل", "w": ["نهر", "بئر", "ماء"], "n": "فشُفي بإذن الله."}, {"q": "من بقي مع أيوب في بلائه؟", "c": "زوجته", "w": ["أصدقاؤه", "جيرانه", "أبناؤه"], "n": "تخدمه وتصبر معه."}, {"q": "ماذا أمره الله أن يفعل ليبرّ بيمينه؟", "c": "يضرب زوجته بحزمة أعواد ضربة واحدة", "w": ["يتصدق بماله", "يصوم شهرًا", "يعتق رقبة"], "n": "من رحمته بهما."}], "q": {"q": "ماذا قال أيوب في دعائه؟", "c": "أني مسني الضر وأنت أرحم الراحمين", "w": ["ربّ ارحمني ولا تبتلني", "اللهم اشفني الآن", "ربّ أعطني ما طلب قومي"], "n": "دعاء مليء بالأدب."}}, {"id": 68, "ch": 9, "t": "شعيب عليه السلام", "s": "النبي الذي نهى عن التطفيف.", "p": ["أرسل الله شعيبًا إلى أهل مدين، وهي أرض في شمال غرب الجزيرة العربية، وكانوا تجارًا يتعاملون بالمكيال والميزان. فكان فيهم غش وتطفيف، يأخذون بالزيادة ويعطون بالنقص.", "فدعاهم شعيب إلى عبادة الله وحده وقال: أوفوا الكيل والميزان ولا تبخسوا الناس أشياءهم ولا تفسدوا في الأرض بعد إصلاحها. ويُروى أنه لُقّب بخطيب الأنبياء لحسن بيانه.", "وكانوا يقعدون بكل صراط يوعدون ويصدّون عن سبيل الله، فقال لهم: لا تقعدوا بكل صراط. وقال: ما أريد أن أخالفكم إلى ما أنهاكم عنه، إن أريد إلا الإصلاح ما استطعت.", "فسخروا منه وقالوا: يا شعيب أصلاتك تأمرك أن نترك ما يعبد آباؤنا أو أن نفعل في أموالنا ما نشاء؟ وهددوه بالرجم لولا رهطه، وقالوا لمن آمن: لئن اتبعتم شعيبًا إنكم إذن لخاسرون.", "فأخذتهم الرجفة وأصبحوا في دارهم جاثمين، وفي سورة الشعراء أنه كان عذاب يوم الظلّة. وقد ذُكر في القرآن أن موسى عليه السلام لما فرّ من مصر وصل إلى مدين فتزوج ابنة رجل صالح، قيل هو شعيب، والله أعلم."], "f": ["الأمانة في التجارة جزء من الإيمان.", "الإصلاح وظيفة الأنبياء، والاستطاعة حدّ المسؤولية."], "qs": [{"q": "إلى أي قوم أُرسل شعيب؟", "c": "مدين", "w": ["ثمود", "عاد", "سبأ"], "n": "وكانوا تجارًا."}, {"t": "tf", "q": "كان قوم شعيب يطففون المكيال والميزان.", "c": true, "n": "فنهاهم عن ذلك."}, {"t": "fill", "q": "أوفوا الكيل والميزان ولا ___ الناس أشياءهم.", "c": "تبخسوا", "w": ["تخدعوا", "تقتلوا", "تهجروا"], "n": "من وصايا شعيب."}, {"q": "بماذا أُهلك قوم شعيب؟", "c": "الرجفة", "w": ["الطوفان", "الريح", "الخسف"], "n": "فأصبحوا جاثمين."}, {"q": "بماذا لُقّب شعيب لحسن بيانه؟", "c": "خطيب الأنبياء", "w": ["كليم الله", "خليل الله", "روح الله"], "n": "ورد ذلك في بعض الآثار."}], "q": {"q": "إلى أي قوم أُرسل شعيب؟", "c": "مدين", "w": ["ثمود", "عاد", "سبأ"], "n": "وكانوا تجارًا."}}, {"id": 69, "ch": 9, "t": "موسى عليه السلام", "s": "كليم الله وأكثر الأنبياء ذكرًا في القرآن.", "p": ["وُلد موسى في زمن فرعون الذي كان يذبّح أبناء بني إسرائيل ويستحيي نساءهم. فألهم الله أمه أن تضعه في تابوت وتلقيه في اليم، وقال لها: ولا تخافي ولا تحزني إنا رادّوه إليك وجاعلوه من المرسلين.", "فالتقطه آل فرعون، وقالت امرأة فرعون: قرّة عين لي ولك لا تقتلوه. وحُرّمت عليه المراضع فجاءت أخته تدلّهم على مرضع، فرُدّ إلى أمه لتقرّ عينها. ونشأ في بيت فرعون.", "ولما بلغ أشدّه وكّز رجلًا من القبط فقضى عليه خطأً، فخرج من مصر خائفًا إلى مدين، فسقى لابنتي الرجل الصالح وتزوج إحداهما، وعمل عنده سنين.", "وفي طريق عودته رأى نارًا في جانب الطور، فلما أتاها نودي: يا موسى إني أنا ربك فاخلع نعليك إنك بالواد المقدس طوى. وأُعطي العصا واليد البيضاء، وأُمر بالذهاب إلى فرعون وسأل ربه أن يشرك أخاه هارون في الأمر.", "ودعا فرعون بالحسنى وأراه الآيات، فاتهمه بالسحر وجمع السحرة ليوم الزينة، فألقى موسى عصاه فإذا هي تلقف ما يأفكون، فسجد السحرة وقالوا: آمنّا برب هارون وموسى. وأصرّ فرعون على كفره وعذّب من آمن.", "فأمر الله موسى أن يسري بعباده ليلًا، فلحقهم فرعون وجنوده، وكان البحر أمامهم، فأمره الله أن يضرب بعصاه البحر فانفلق «فكان كل فِرق كالطود العظيم». فعبر بنو إسرائيل وأغرق الله فرعون وجنوده."], "f": ["تدبير الله يسبق خوف الإنسان.", "الداعية يدعو بالحسنى ولو كان المدعوّ طاغية."], "qs": [{"q": "ماذا ألهم الله أمّ موسى أن تفعل به؟", "c": "تضعه في تابوت وتلقيه في اليم", "w": ["تهرب به إلى مصر", "تسلّمه لفرعون", "تخفيه في بيتها"], "n": "ووعدها بأن يرده إليها."}, {"t": "tf", "q": "أُمر موسى أن يخلع نعليه عند الوادي المقدس.", "c": true, "n": "وادي طوى."}, {"t": "fill", "q": "قال السحرة: آمنّا برب هارون و___.", "c": "موسى", "w": ["إبراهيم", "يعقوب", "عيسى"], "n": "بعد أن رأوا العصا."}, {"q": "ماذا فعل موسى حين أدركه فرعون عند البحر؟", "c": "ضرب البحر بعصاه فانفلق", "w": ["صعد جبلًا", "بنى سفينة", "صالح فرعون"], "n": "فعبر بنو إسرائيل."}, {"t": "ord", "q": "رتّب أحداث القصة:", "items": ["أُلقي في اليم في تابوت", "فرّ إلى مدين", "نودي عند الطور وأُرسل إلى فرعون", "انفلق البحر وغرق فرعون"], "n": "هكذا تتابعت أحداث قصته."}], "q": {"q": "ماذا ألهم الله أمّ موسى أن تفعل به؟", "c": "تضعه في تابوت وتلقيه في اليم", "w": ["تهرب به إلى مصر", "تسلّمه لفرعون", "تخفيه في بيتها"], "n": "ووعدها بأن يرده إليها."}}, {"id": 70, "ch": 9, "t": "داود عليه السلام", "s": "النبي الملك صاحب الزبور.", "p": ["كان داود فتى من بني إسرائيل، لما خرج الجيش مع طالوت لقتال جالوت وكان جبارًا، كان داود في جنده. فقتل جالوت بإذن الله، فكانت بداية شهرته. وقد ذكر القرآن أن الله آتاه الملك والحكمة وعلّمه مما يشاء.", "وأعطاه الله الزبور، وكان صوته جميلًا في الذكر، فسخّر معه الجبال والطير تسبّح معه بالعشي والإشراق، فكان إذا سبّح سبّحت معه.", "وألان الله له الحديد، فكان يصنع الدروع السابغات ويقدّر في السرد. وكان ﷺ يقول عنه: «ما أكل أحد طعامًا قط خيرًا من أن يأكل من عمل يده، وإن نبي الله داود كان يأكل من عمل يده».", "وكان أحب الصيام إلى الله صيام داود: يصوم يومًا ويفطر يومًا، وأحب القيام إلى الله قيام داود: ينام نصف الليل ويقوم ثلثه وينام سدسه. فجمع بين الملك والعبادة.", "ومن لطائف قصته أن خصمين تسوّرا عليه المحراب يختصمان في نعجة، فعلم داود أن الله فتنه فاستغفر ربه وخرّ راكعًا وأناب. وقال الله له: يا داود إنا جعلناك خليفة في الأرض فاحكم بين الناس بالحق ولا تتبع الهوى."], "f": ["الجمع بين العمل والعبادة طريق الأنبياء.", "القاضي العادل يرجع إلى ربه إذا ظنّ أنه أخطأ."], "qs": [{"q": "من الذي قتل جالوت؟", "c": "داود", "w": ["سليمان", "طالوت", "هارون"], "n": "بإذن الله."}, {"t": "tf", "q": "أعطى الله داود كتابًا اسمه الزبور.", "c": true, "n": "وكان يسبّح معه الجبال والطير."}, {"t": "fill", "q": "وألان الله له ___ فصنع الدروع.", "c": "الحديد", "w": ["النحاس", "الذهب", "الصخر"], "n": "السابغات."}, {"q": "ما الصيام الذي وصفه النبي ﷺ بأنه أحب الصيام إلى الله؟", "c": "صيام داود: يومًا وإفطار يومًا", "w": ["صيام الدهر", "صيام الاثنين والخميس", "صيام شعبان"], "n": "كما في الحديث الصحيح."}, {"q": "مم كان يأكل داود؟", "c": "من عمل يده", "w": ["من الغنائم", "من هدايا الملوك", "من الزكاة"], "n": "فكان يصنع الدروع."}], "q": {"q": "من الذي قتل جالوت؟", "c": "داود", "w": ["سليمان", "طالوت", "هارون"], "n": "بإذن الله."}}, {"id": 71, "ch": 9, "t": "سليمان عليه السلام", "s": "الملك الذي سخّر الله له الريح والجن.", "p": ["ورث سليمان النبوة والملك عن أبيه داود، وسأل ربه: رب هب لي ملكًا لا ينبغي لأحد من بعدي. فأعطاه الله علم منطق الطير وسخّر له الريح تجري بأمره رخاءً، وسخّر له الجن يعملون له ما يشاء من محاريب وتماثيل وجفان.", "وفي يوم مرّ بجنوده على وادي النمل فقالت نملة: يا أيها النمل ادخلوا مساكنكم لا يحطمنّكم سليمان وجنوده وهم لا يشعرون. فتبسّم ضاحكًا من قولها وقال: رب أوزعني أن أشكر نعمتك التي أنعمت عليّ.", "وتفقّد الطير فلم يجد الهدهد، فتوعّده إن لم يأتِ بعذر. فجاء الهدهد بنبأ يقين من سبأ، وأخبره أنه وجد امرأة تملكهم ولها عرش عظيم، وهم يسجدون للشمس من دون الله.", "فكتب سليمان إليها كتابًا: إنه من سليمان وإنه بسم الله الرحمن الرحيم ألا تعلوا علي وأتوني مسلمين. فجاءت بلقيس بعد مشاورة قومها، وأُحضر لها عرشها قبل أن يرتدّ إليه طرفه بفضل من الله.", "وأدخلها الصرح الممرّد من قوارير فحسبته لجّة وكشفت عن ساقيها، فقال: إنه صرح ممرّد من قوارير. فقالت: رب إني ظلمت نفسي وأسلمت مع سليمان لله رب العالمين.", "ومات سليمان وهو متّكئ على عصاه، فلم تعلم الجن بموته حتى أكلت الأرضة عصاه فخرّ، فتبيّنت الجن أن لو كانوا يعلمون الغيب ما لبثوا في العذاب المهين."], "f": ["النعمة تُقابَل بالشكر لا بالفخر.", "الملك الحقّ أن يُسخَّر في الدعوة والعدل."], "qs": [{"q": "من الذي جاء سليمان بنبأ سبأ؟", "c": "الهدهد", "w": ["الغراب", "النملة", "الريح"], "n": "وجد امرأة تملكهم."}, {"t": "tf", "q": "سمع سليمان قول النملة وتبسّم.", "c": true, "n": "وقال رب أوزعني أن أشكر نعمتك."}, {"t": "fill", "q": "اسم ملكة سبأ المشهور في كتب التفسير هو ___.", "c": "بلقيس", "w": ["هاجر", "آسية", "مريم"], "n": "فأسلمت مع سليمان."}, {"q": "ما الذي أسقط سليمان بعد موته؟", "c": "أكلت الأرضة عصاه", "w": ["هبّت ريح عاصفة", "وقع عن العرش", "ضربه الجن"], "n": "فتبيّن للجن."}, {"t": "match", "q": "صِل كل كائن بما سُخّر لسليمان أو ورد معه:", "pairs": [["الريح", "تجري بأمره"], ["الجن", "يعملون المحاريب"], ["الهدهد", "جاء بنبأ سبأ"], ["النملة", "حذّرت قومها"]], "n": "من آيات سورة النمل."}], "q": {"q": "من الذي جاء سليمان بنبأ سبأ؟", "c": "الهدهد", "w": ["الغراب", "النملة", "الريح"], "n": "وجد امرأة تملكهم."}}, {"id": 72, "ch": 9, "t": "يونس عليه السلام", "s": "صاحب الحوت.", "p": ["أرسل الله يونس إلى أهل نينوى، وكانوا نحو مئة ألف أو يزيدون. فدعاهم زمانًا فلم يستجيبوا، فغضب وخرج مغاضبًا ظنًّا منه أن الله لن يضيّق عليه، وترك قومه قبل أن يؤذن له.", "فركب سفينة مملوءة، فلما اضطربت الأمواج اقترع أهلها لإلقاء أحدهم، فأصابت القرعة يونس، فكان من المدحَضين. فألقي في البحر فالتقمه الحوت وهو مليم.", "فنادى في الظلمات: «لا إله إلا أنت سبحانك إني كنت من الظالمين». فاستجاب الله له ونجّاه من الغم، وقال القرآن: فلولا أنه كان من المسبّحين للبث في بطنه إلى يوم يبعثون.", "ونبذه الحوت بالعراء وهو سقيم، وأنبت الله عليه شجرة من يقطين تظلّه وتغذّيه. ثم أرسله إلى مئة ألف أو يزيدون.", "وحين رأى قومه العذاب اقترب آمنوا، فكشف الله عنهم العذاب وفاءً لتوبتهم، وهم القوم الوحيدون الذين نفعهم إيمانهم بعد رؤية العذاب. فمتّعهم الله إلى حين."], "f": ["دعاء الكرب «لا إله إلا أنت سبحانك إني كنت من الظالمين» من أعظم الأدعية.", "الصبر على الدعوة وعدم الاستعجال في ترك الميدان."], "qs": [{"q": "ما الذي التقم يونس؟", "c": "حوت", "w": ["سمكة صغيرة", "تمساح", "ثعبان"], "n": "فنادى في الظلمات."}, {"t": "tf", "q": "آمن قوم يونس فكشف الله عنهم العذاب.", "c": true, "n": "وتمتعوا إلى حين."}, {"t": "fill", "q": "فنادى في الظلمات أن لا إله إلا أنت ___ إني كنت من الظالمين.", "c": "سبحانك", "w": ["ربّنا", "اغفر لي", "سبحان ربّي"], "n": "دعاء الكرب."}, {"q": "ما الشجرة التي أنبتها الله على يونس؟", "c": "يقطين", "w": ["نخلة", "زيتون", "سدر"], "n": "فكانت له ظلًّا وغذاءً."}, {"t": "ord", "q": "رتّب أحداث القصة:", "items": ["غادر قومه مغاضبًا", "ركب السفينة وأُلقي في البحر", "التقمه الحوت فدعا ربه", "نُبذ بالعراء وأنبت الله عليه يقطينًا"], "n": "ثم آمن قومه."}], "q": {"q": "ما الذي التقم يونس؟", "c": "حوت", "w": ["سمكة صغيرة", "تمساح", "ثعبان"], "n": "فنادى في الظلمات."}}, {"id": 73, "ch": 9, "t": "زكريا ويحيى عليهما السلام", "s": "دعاء الشيخ الكبير وبِرّ الولد.", "p": ["كان زكريا نبيًّا من بني إسرائيل، وكفل مريم بنت عمران حين نذرتها أمها لخدمة المسجد. وكان كلما دخل عليها المحراب وجد عندها رزقًا، فقال: يا مريم أنّى لك هذا؟ قالت: هو من عند الله إن الله يرزق من يشاء بغير حساب.", "فلما رأى ذلك تحرّك قلبه بالطلب، وكان قد بلغ من الكبر عتيًّا وامرأته عاقر، فنادى ربه نداءً خفيًّا: «ربّ لا تذرني فردًا وأنت خير الوارثين». وقال: رب إني وهن العظم مني واشتعل الرأس شيبًا ولم أكن بدعائك رب شقيًّا.", "فبشّرته الملائكة بغلام اسمه يحيى لم يجعل الله له من قبل سميًّا. فقال زكريا: أنّى يكون لي غلام؟ فقال: كذلك قال ربك هو عليّ هين. وجعل الله له آية: ألا يكلم الناس ثلاث ليال سويًّا، فخرج على قومه من المحراب فأوحى إليهم أن سبّحوا بكرة وعشيًّا.", "وولد يحيى، وقال الله له: «يا يحيى خذ الكتاب بقوة وآتيناه الحكم صبيًّا». ووصفه القرآن بأنه حنان من لدنا وزكاة وكان تقيًّا بارًّا بوالديه ولم يكن جبارًا عصيًّا.", "وسلام عليه يوم وُلد ويوم يموت ويوم يُبعث حيًّا. وكان يحيى زاهدًا عابدًا مصدّقًا بعيسى ابن مريم."], "f": ["لا يأس من رحمة الله مهما كبر العمر.", "الدعاء الخفيّ الصادق أقرب إلى الإجابة."], "qs": [{"q": "من كفل مريم؟", "c": "زكريا", "w": ["يوسف النجار", "عمران", "هارون"], "n": "وكان نبيًّا."}, {"t": "tf", "q": "طلب زكريا ولدًا وهو قد بلغ الكبر وامرأته عاقر.", "c": true, "n": "فبشّره الله بيحيى."}, {"t": "fill", "q": "ربّ لا تذرني ___ وأنت خير الوارثين.", "c": "فردًا", "w": ["وحيدًا", "فقيرًا", "ضعيفًا"], "n": "من دعاء زكريا."}, {"q": "ما آية زكريا بعد البشارة؟", "c": "ألا يكلم الناس ثلاث ليال سويًّا", "w": ["أن يرى الملائكة", "أن يعود شابًّا", "أن يُرزق مالًا"], "n": "فأوحى إليهم أن سبّحوا."}, {"q": "بماذا وُصف يحيى تجاه والديه؟", "c": "بارًّا بهما", "w": ["غليظًا عليهما", "بعيدًا عنهما", "مشغولًا عنهما"], "n": "ولم يكن جبارًا عصيًّا."}], "q": {"q": "من كفل مريم؟", "c": "زكريا", "w": ["يوسف النجار", "عمران", "هارون"], "n": "وكان نبيًّا."}}, {"id": 74, "ch": 9, "t": "عيسى عليه السلام", "s": "كلمة الله وروح منه.", "p": ["نذرت أم مريم ما في بطنها لله، فولدت مريم، وكفلها زكريا، فنشأت في المحراب عابدة. ثم انتبذت مكانًا شرقيًّا واتخذت من دونهم حجابًا، فأرسل الله إليها جبريل في صورة بشر سويّ، فقالت: إني أعوذ بالرحمن منك إن كنت تقيًّا.", "فقال: إنما أنا رسول ربك لأهب لك غلامًا زكيًّا. قالت: أنّى يكون لي غلام ولم يمسسني بشر؟ قال: كذلك قال ربك هو عليّ هيّن. ونُفخ فيها من روح الله فحملت بعيسى بأمر الله.", "ولما جاءها المخاض أجأها إلى جذع النخلة، فناداها من تحتها (قيل عيسى وقيل جبريل) ألا تحزني: «هزّي إليك بجذع النخلة تُساقط عليك رطبًا جنيًّا». وأمرها أن تنذر للرحمن صومًا فلا تكلّم أحدًا.", "فأتت قومها به تحمله، فاتهموها، فأشارت إليه. فتكلم في المهد: «إني عبد الله آتاني الكتاب وجعلني نبيًّا وجعلني مباركًا أينما كنت». فكانت أول آياته.", "وأرسله الله إلى بني إسرائيل، وأيّده بمعجزات بإذن الله: يبرئ الأكمه والأبرص، ويحيي الموتى، وينبئهم بما يأكلون وما يدّخرون في بيوتهم. وصدّقه الحواريون وقالوا: نحن أنصار الله.", "ولما همّوا بقتله قال الله: «وما قتلوه وما صلبوه ولكن شُبّه لهم»، فرفعه الله إليه. وأخبر النبي ﷺ أنه سينزل في آخر الزمان حكَمًا عدلًا فيكسر الصليب ويقتل الخنزير."], "f": ["المعجزات كلها بإذن الله، والأنبياء عباد لله.", "التوكل على الله يزيل خوف الإنسان."], "qs": [{"q": "ماذا قال عيسى حين تكلم في المهد؟", "c": "إني عبد الله آتاني الكتاب وجعلني نبيًّا", "w": ["أنا ابن الله", "أنا الملك", "لا تحزني يا قوم"], "n": "فكانت أول آياته."}, {"t": "tf", "q": "جاء عيسى بمعجزاته بإذن الله.", "c": true, "n": "من إبراء الأكمه وإحياء الموتى."}, {"t": "fill", "q": "هزّي إليك بجذع ___ تُساقط عليك رطبًا جنيًّا.", "c": "النخلة", "w": ["الزيتونة", "التينة", "الشجرة"], "n": "قال لها وهي في المخاض."}, {"q": "من الذي أرسله الله إلى مريم؟", "c": "جبريل عليه السلام", "w": ["ميكائيل", "إسرافيل", "زكريا"], "n": "في صورة بشر سويّ."}, {"t": "match", "q": "صِل كل معجزة بما يناسبها:", "pairs": [["التكلم في المهد", "شهادة بعبوديته لله"], ["إبراء الأكمه", "إعادة البصر لمن وُلد أعمى"], ["إحياء الموتى", "بإذن الله"], ["التنبؤ بما في البيوت", "علم بما يأكلون ويدخرون"]], "n": "كلها بإذن الله."}], "q": {"q": "ماذا قال عيسى حين تكلم في المهد؟", "c": "إني عبد الله آتاني الكتاب وجعلني نبيًّا", "w": ["أنا ابن الله", "أنا الملك", "لا تحزني يا قوم"], "n": "فكانت أول آياته."}}];
