  Object.assign(META,{"60": ["أول الأنبياء", "الجنة ثم الأرض"], "61": ["بعد آدم بقرون", "قومه في الأرض"], "62": ["قوم عاد", "الأحقاف جنوب الجزيرة"], "63": ["قوم ثمود", "الحِجر شمال الحجاز"], "64": ["أبو الأنبياء", "العراق والشام ومكة"], "65": ["معاصر لإبراهيم", "سدوم قرب البحر الميت"], "66": ["ابن يعقوب", "كنعان ثم مصر"], "67": ["الصبر على البلاء", "غير محدّد في النص"], "68": ["أهل مدين", "شمال غرب الجزيرة"], "69": ["أكثر ذكرًا في القرآن", "مصر وسيناء"], "70": ["نبي وملك", "بيت المقدس"], "71": ["نبي وملك", "بيت المقدس"], "72": ["صاحب الحوت", "نينوى"], "73": ["كافل مريم", "بيت المقدس"], "74": ["كلمة الله ومسيحه", "فلسطين"]});
  const NEWS6=[{"id": 75, "ch": 9, "t": "إدريس وإلياس واليسع وذو الكفل", "s": "أنبياء ذُكروا في القرآن باختصار.", "p": ["ذكر الله إدريس في سورة مريم فقال: «واذكر في الكتاب إدريس إنه كان صدّيقًا نبيًّا ورفعناه مكانًا عليًّا». وقال المفسرون إن رفعه مكانًا عليًّا يعني علوّ منزلته وذكره عند الله، ولم يفصّل القرآن قصته.", "وذكر الله ذا الكفل مع إسماعيل وإدريس فقال: «كلٌّ من الصابرين»، وفي سورة ص: «وكلٌّ من الأخيار». ولم يذكر القرآن تفاصيل قصته، وللمفسرين فيها أقوال كثيرة، وفي نبوته خلاف بينهم.", "وأما إلياس فأرسله الله إلى قوم يعبدون صنمًا اسمه «بعل». فقال لهم: «ألا تتقون أتدعون بعلًا وتذرون أحسن الخالقين الله ربكم ورب آبائكم الأولين». فكذّبوه، ونجّى الله إلياس وعباده المخلصين، وأبقى له ذكرًا حسنًا: «سلام على إل ياسين».", "وأما اليسع فذكره الله في سورة الأنعام ضمن الأنبياء الذين فضّلهم على العالمين: «وإسماعيل واليسع ويونس ولوطًا وكلًّا فضّلنا على العالمين».", "وفي هذا درس أن القرآن لم يقصّ علينا قصص جميع الأنبياء، قال تعالى: «ورسلًا قد قصصناهم عليك من قبل ورسلًا لم نقصصهم عليك». فنؤمن بهم كلهم، وإن لم نعرف تفاصيل قصصهم."], "f": ["الإيمان بالأنبياء كلهم دون تفريق، وإن لم نعرف قصصهم.", "دعوة الأنبياء واحدة: عبادة الله وحده."], "qs": [{"t": "tf", "q": "ذكر القرآن قصص جميع الأنبياء بالتفصيل.", "c": false, "n": "منهم من لم يقصصهم الله علينا."}, {"t": "fill", "q": "ألا تتقون أتدعون ___ وتذرون أحسن الخالقين.", "c": "بعلًا", "w": ["وَدًّا", "هُبَل", "اللات"], "n": "قالها إلياس لقومه."}, {"q": "ما معنى «ورفعناه مكانًا عليًّا» عند المفسرين؟", "c": "رفع الله منزلته وذكره", "w": ["أنه سكن الجبل", "أنه نزل من السماء", "أنه صار ملكًا"], "n": "ولم يفصّل القرآن قصته."}, {"t": "match", "q": "صِل كل نبي بما ذُكر عنه:", "pairs": [["إدريس", "صدّيقًا نبيًّا"], ["إلياس", "دعا قومه عن عبادة بعل"], ["ذو الكفل", "من الصابرين والأخيار"], ["اليسع", "ذُكر في الأنعام بين المفضّلين"]], "n": "من آيات القرآن الكريم."}, {"q": "أي سورة ذُكر فيها إدريس بقوله «إنه كان صدّيقًا نبيًّا»؟", "c": "مريم", "w": ["الأنعام", "الأحقاف", "الصافات"], "n": "سورة مريم."}], "q": {"t": "tf", "q": "ذكر القرآن قصص جميع الأنبياء بالتفصيل.", "c": false, "n": "منهم من لم يقصصهم الله علينا."}}, {"id": 76, "ch": 9, "t": "إسماعيل عليه السلام", "s": "جدّ العرب وباني الكعبة مع أبيه.", "p": ["وُلد إسماعيل لإبراهيم من هاجر، فأمر الله إبراهيم أن يسكنهما عند البيت الحرام في وادٍ لا زرع فيه ولا ماء. فتركهما ومعهما جراب تمر وسقاء ماء ومضى. فقالت هاجر: «آلله أمرك بهذا؟» قال: نعم. قالت: «إذن لا يضيّعنا».", "ولما نفد الماء وعطش الطفل، سعت هاجر بين الصفا والمروة سبع مرات تبحث عن ماء. فنزل جبريل عليه السلام فضرب الأرض فنبع ماء زمزم. وقال النبي ﷺ: «يرحم الله أم إسماعيل، لو تركت زمزم لكانت عينًا معينًا». ومن سعيها أُخذت شعيرة السعي في الحج والعمرة.", "ومرّت قبيلة جُرهم بالوادي فرأت الطير يحوم، فعلمت أن فيه ماءً، فاستأذنت هاجر أن تنزل عندها فأذنت. فنشأ إسماعيل بين جُرهم وتعلّم منهم العربية وتزوج منهم.", "وجاءت لحظة الابتلاء حين رأى إبراهيم في المنام أنه يذبح ابنه، فقال إسماعيل: «يا أبتِ افعل ما تُؤمر ستجدني إن شاء الله من الصابرين». فلما استسلما فداه الله بذبح عظيم.", "ثم جاء إبراهيم فرفعا معًا قواعد الكعبة، إبراهيم يبني وإسماعيل يناوله الحجارة، وهما يقولان: «ربنا تقبل منا إنك أنت السميع العليم».", "ووصفه الله بقوله: «إنه كان صادق الوعد وكان رسولًا نبيًّا وكان يأمر أهله بالصلاة والزكاة وكان عند ربه مرضيًّا». وإلى إسماعيل ينتسب النبي ﷺ."], "f": ["التوكل على الله يحوّل الصحراء إلى مصدر رزق.", "صدق الوعد من أخلاق الأنبياء."], "qs": [{"q": "ماذا فعلت هاجر حين نفد الماء؟", "c": "سعت بين الصفا والمروة", "w": ["رجعت إلى الشام", "نادت على قبيلة", "حفرت بئرًا"], "n": "فنبع زمزم."}, {"t": "tf", "q": "وصف الله إسماعيل بأنه صادق الوعد.", "c": true, "n": "في سورة مريم."}, {"t": "fill", "q": "وكان يأمر أهله بالصلاة و___.", "c": "الزكاة", "w": ["الصيام", "الحج", "الجهاد"], "n": "وكان عند ربه مرضيًّا."}, {"t": "match", "q": "صِل كل اسم بما يناسبه:", "pairs": [["هاجر", "أم إسماعيل"], ["جُرهم", "القبيلة التي نزلت عند زمزم"], ["زمزم", "ماء نبع لإسماعيل"], ["الصفا والمروة", "موضع سعي هاجر"]], "n": "من أحداث قصته."}, {"t": "ord", "q": "رتّب أحداث القصة:", "items": ["تركهما إبراهيم عند البيت", "نبع ماء زمزم", "نزلت جُرهم عند المكان", "رفع إبراهيم وإسماعيل قواعد الكعبة"], "n": "هكذا بدأت عمارة مكة."}], "q": {"q": "ماذا فعلت هاجر حين نفد الماء؟", "c": "سعت بين الصفا والمروة", "w": ["رجعت إلى الشام", "نادت على قبيلة", "حفرت بئرًا"], "n": "فنبع زمزم."}}, {"id": 77, "ch": 9, "t": "إسحاق ويعقوب عليهما السلام", "s": "ابنا وحفيد الخليل، وأبو الأسباط.", "p": ["جاءت الملائكة إبراهيم تبشّره بغلام عليم، وكانت امرأته سارة قائمة فضحكت. فبشّرتها الملائكة: «بإسحاق ومن وراء إسحاق يعقوب». فقالت متعجبة: «يا ويلتى أألد وأنا عجوز وهذا بعلي شيخًا؟» فقالوا: «أتعجبين من أمر الله؟».", "ووصف الله إبراهيم وإسحاق ويعقوب بقوله: «أولي الأيدي والأبصار»، أي أصحاب القوة في العبادة والبصيرة في الدين، وأنهم من المصطفين الأخيار.", "ويعقوب هو إسرائيل، وقد ذكر القرآن اسمه هذا. وكان له اثنا عشر ولدًا هم الأسباط، ومنهم يوسف عليه السلام، ومن ذريته جاء أنبياء كثيرون من بني إسرائيل.", "ولما فقد يوسف صبر صبرًا جميلًا، وقال: «إنما أشكو بثّي وحزني إلى الله». وابيضّت عيناه من الحزن فهو كظيم. ومع ذلك لم ييأس، فأمر أبناءه أن يبحثوا عن يوسف وأخيه، وقال: «ولا تيأسوا من رَوح الله إنه لا ييأس من رَوح الله إلا القوم الكافرون».", "وعند حضور الموت جمع أبناءه وسألهم: «ما تعبدون من بعدي؟» فقالوا: «نعبد إلهك وإله آبائك إبراهيم وإسماعيل وإسحاق إلهًا واحدًا ونحن له مسلمون». فاطمأن أن الوصية بالتوحيد قد بلغت."], "f": ["اليأس من رحمة الله ليس من أخلاق المؤمنين.", "أعظم وصية للأبناء هي التوحيد."], "qs": [{"q": "ما الذي بُشّرت به سارة؟", "c": "إسحاق ومن وراءه يعقوب", "w": ["إسماعيل", "يوسف", "هود"], "n": "وكانت عجوزًا."}, {"t": "tf", "q": "إسرائيل هو اسم يعقوب عليه السلام.", "c": true, "n": "ذكره القرآن بهذا الاسم."}, {"t": "fill", "q": "إنما أشكو بثّي وحزني إلى ___.", "c": "الله", "w": ["الناس", "أبنائي", "الملك"], "n": "قالها يعقوب."}, {"q": "من هم الأسباط؟", "c": "أبناء يعقوب الاثنا عشر", "w": ["أبناء إبراهيم", "جنود سليمان", "أصحاب الكهف"], "n": "ومنهم يوسف."}, {"t": "match", "q": "صِل كل اسم بما يناسبه:", "pairs": [["إسحاق", "ابن إبراهيم وسارة"], ["يعقوب", "والد يوسف"], ["سارة", "بُشّرت وهي عجوز"], ["الأسباط", "أبناء يعقوب"]], "n": "من قصة بيت إبراهيم."}], "q": {"q": "ما الذي بُشّرت به سارة؟", "c": "إسحاق ومن وراءه يعقوب", "w": ["إسماعيل", "يوسف", "هود"], "n": "وكانت عجوزًا."}}, {"id": 78, "ch": 9, "t": "هارون عليه السلام", "s": "وزير موسى وعونه في الدعوة.", "p": ["حين كلّف الله موسى بالذهاب إلى فرعون دعا ربه: «واجعل لي وزيرًا من أهلي هارون أخي اشدد به أزري وأشركه في أمري». وقال: «وأخي هارون هو أفصح مني لسانًا فأرسله معي ردءًا يصدّقني». فاستجاب الله: «قد أوتيت سؤلك يا موسى».", "فذهب الأخوان إلى فرعون، وأمرهما الله بالرفق: «فقولا له قولًا لينًا لعله يتذكر أو يخشى». وكان هارون عونًا لموسى في الدعوة والصبر.", "ولما ذهب موسى لميقات ربه استخلف هارون في قومه، وقال له: «اخلفني في قومي وأصلح ولا تتبع سبيل المفسدين».", "فصنع السامري لبني إسرائيل عجلًا جسدًا له خوار، فافتتنوا به وعبدوه. فقال لهم هارون: «يا قوم إنما فُتنتم به وإن ربكم الرحمن فاتبعوني وأطيعوا أمري». فقالوا: «لن نبرح عليه عاكفين حتى يرجع إلينا موسى».", "فرجع موسى غضبان أسفًا، وأخذ برأس أخيه يجرّه إليه، فقال هارون: «يا ابن أم لا تأخذ بلحيتي ولا برأسي إني خشيت أن تقول فرّقت بين بني إسرائيل ولم ترقب قولي». فدعا موسى: «رب اغفر لي ولأخي وأدخلنا في رحمتك».", "وفي القصة أن هارون أنكر المنكر بحسب استطاعته، وخشي الفرقة، فكان صبره من أخلاق الدعاة."], "f": ["الأخوّة الصالحة عون على الدعوة.", "الإنكار بالحكمة يحفظ الجماعة من الفرقة."], "qs": [{"q": "ماذا طلب موسى من ربه ليعينه على الدعوة؟", "c": "أن يرسل معه أخاه هارون", "w": ["أن يعطيه جندًا", "أن يرسله وحده", "أن يكلّم فرعون عنه"], "n": "فاستجاب الله له."}, {"t": "tf", "q": "أمر هارون بني إسرائيل بعبادة العجل.", "c": false, "n": "بل نهاهم وقال إنما فُتنتم به."}, {"t": "fill", "q": "يا ابن أمّ لا تأخذ بلحيتي ولا ___.", "c": "برأسي", "w": ["بيدي", "بقميصي", "بردائي"], "n": "قالها هارون لموسى."}, {"q": "من الذي صنع العجل لبني إسرائيل؟", "c": "السامري", "w": ["هارون", "فرعون", "هامان"], "n": "ففتنهم به."}, {"t": "ord", "q": "رتّب أحداث القصة:", "items": ["طلب موسى هارون وزيرًا", "ذهبا إلى فرعون", "استخلف موسى هارون وذهب للميقات", "صُنع العجل وعبده القوم", "رجع موسى فأمسك برأس أخيه"], "n": "ثم دعا موسى لهما بالمغفرة."}], "q": {"q": "ماذا طلب موسى من ربه ليعينه على الدعوة؟", "c": "أن يرسل معه أخاه هارون", "w": ["أن يعطيه جندًا", "أن يرسله وحده", "أن يكلّم فرعون عنه"], "n": "فاستجاب الله له."}}, {"id": 79, "ch": 9, "t": "أولو العزم من الرسل", "s": "خمسة رسل صبروا على أعظم الشدائد.", "p": ["قال الله لنبيه ﷺ: «فاصبر كما صبر أولو العزم من الرسل». والعزم هو الثبات والصبر على الشدائد. وقد اشتهر عند جمهور المفسرين أنهم خمسة، وقيل غير ذلك.", "وقد ذكرهم الله مجتمعين في سورة الشورى: «شرع لكم من الدين ما وصّى به نوحًا والذي أوحينا إليك وما وصّينا به إبراهيم وموسى وعيسى أن أقيموا الدين ولا تتفرقوا فيه». فهم نوح وإبراهيم وموسى وعيسى ومحمد ﷺ.", "نوح صبر ألف سنة إلا خمسين عامًا يدعو قومه. وإبراهيم صبر على النار والغربة والابتلاء بذبح ابنه. وموسى صبر على طغيان فرعون وعناد بني إسرائيل. وعيسى صبر على الجحود والتآمر عليه. ومحمد ﷺ صبر على أذى قريش في مكة وعلى الطائف وأُحد.", "ورسالتهم جميعًا واحدة، قال تعالى: «إنا أوحينا إليك كما أوحينا إلى نوح والنبيين من بعده». وقال النبي ﷺ: «الأنبياء إخوة لعلّات، أمهاتهم شتى ودينهم واحد». أي أن أصل دينهم التوحيد، وإن اختلفت الشرائع.", "وختم الله بهم النبوة بمحمد ﷺ: «ولكن رسول الله وخاتم النبيين». فبقيت رسالته هداية للناس إلى يوم القيامة."], "f": ["الصبر طريق الثبات في الدعوة وفي الحياة.", "وحدة أصل الدين تجمع الأنبياء كلهم."], "qs": [{"q": "كم عدد أولي العزم عند جمهور المفسرين؟", "c": "خمسة", "w": ["ثلاثة", "سبعة", "عشرة"], "n": "نوح وإبراهيم وموسى وعيسى ومحمد ﷺ."}, {"t": "tf", "q": "دين الأنبياء كلهم في أصله واحد وهو التوحيد.", "c": true, "n": "وإن اختلفت الشرائع."}, {"t": "fill", "q": "ولكن رسول الله وخاتم ___.", "c": "النبيين", "w": ["المرسلين", "الرسل", "الأنبياء"], "n": "آية في سورة الأحزاب."}, {"t": "match", "q": "صِل كل رسول بما اشتُهر به من صبره:", "pairs": [["نوح", "ألف سنة إلا خمسين عامًا"], ["إبراهيم", "النار والابتلاء بالذبح"], ["موسى", "فرعون وعناد بني إسرائيل"], ["محمد ﷺ", "أذى قريش والطائف"]], "n": "من صبر أولي العزم."}, {"t": "ord", "q": "رتّب أولي العزم زمنيًّا:", "items": ["نوح", "إبراهيم", "موسى", "عيسى", "محمد ﷺ"], "n": "وهو خاتمهم."}], "q": {"q": "كم عدد أولي العزم عند جمهور المفسرين؟", "c": "خمسة", "w": ["ثلاثة", "سبعة", "عشرة"], "n": "نوح وإبراهيم وموسى وعيسى ومحمد ﷺ."}}];
