  (function(){const r={"t": "إدريس عليه السلام", "s": "النبي الصدّيق الذي رفعه الله مكانًا عليًّا.", "p": ["ذكر الله إدريس في سورة مريم فقال: «واذكر في الكتاب إدريس إنه كان صدّيقًا نبيًّا ورفعناه مكانًا عليًّا». فجمع له الصدق في القول والعمل مع النبوة.", "وذكره في سورة الأنبياء مع إسماعيل وذي الكفل: «وإسماعيل وإدريس وذا الكفل كلٌّ من الصابرين وأدخلناهم في رحمتنا إنهم من الصالحين». فكان من أهل الصبر والصلاح.", "وقال المفسرون في «ورفعناه مكانًا عليًّا» إنه رفع منزلته عند الله وذكره بين الناس، وقيل غير ذلك. وأما تفاصيل حياته فلم يذكرها القرآن ولا الأحاديث الصحيحة، وما يُروى في بعض الكتب من أخبار عنه مأخوذ من الإسرائيليات فلا يُعتمد عليه.", "وتذكر كتب التفسير والتاريخ أنه من أقدم الأنبياء، وأنه جاء بعد آدم وقبل نوح على المشهور عند بعضهم، وقيل إنه جاء بعد نوح، والله أعلم.", "وقد ثبت في حديث المعراج أن النبي ﷺ لقيه في السماء الرابعة، فرحّب به وقال: «مرحبًا بالأخ الصالح والنبي الصالح». فكان في ذلك تكريم له."], "f": ["الصدق من أعظم صفات الأنبياء.", "ما لا نعلمه من قصصهم نؤمن به إجمالًا."], "qs": [{"t": "fill", "q": "إنه كان ___ نبيًّا.", "c": "صدّيقًا", "w": ["صادقًا", "صالحًا", "شكورًا"], "n": "وصفه الله بذلك في سورة مريم."}, {"q": "في أي سماء لقي النبي ﷺ إدريس ليلة المعراج؟", "c": "الرابعة", "w": ["الثانية", "الثالثة", "الخامسة"], "n": "كما في الصحيحين."}, {"t": "tf", "q": "ذكر القرآن تفاصيل حياة إدريس بشكل مفصّل.", "c": false, "n": "لم يفصّل القرآن قصته."}, {"q": "أي سورة ذُكر فيها إدريس مع إسماعيل وذي الكفل بوصف «من الصابرين»؟", "c": "الأنبياء", "w": ["مريم", "ص", "الأنعام"], "n": "وأدخلناهم في رحمتنا."}, {"t": "match", "q": "صِل كل وصف بمعناه:", "pairs": [["صدّيق", "كثير الصدق"], ["مكانًا عليًّا", "علو المنزلة"], ["من الصابرين", "وصف لإدريس وإسماعيل وذي الكفل"], ["الإسرائيليات", "أخبار لا يُعتمد عليها دون دليل"]], "n": "ما يتعلق بقصة إدريس."}], "q": {"t": "fill", "q": "إنه كان ___ نبيًّا.", "c": "صدّيقًا", "w": ["صادقًا", "صالحًا", "شكورًا"], "n": "وصفه الله بذلك في سورة مريم."}};const o=ST.find(function(x){return x.id===75});Object.assign(o,r);ST.push({"id": 80, "ch": 9, "t": "إلياس واليسع وذو الكفل", "s": "أنبياء ذُكروا في القرآن بإيجاز.", "p": ["ذكر الله إلياس في سورة الصافات فقال: «وإن إلياس لمن المرسلين إذ قال لقومه ألا تتقون أتدعون بعلًا وتذرون أحسن الخالقين الله ربكم ورب آبائكم الأولين». وبعل صنم كانوا يعبدونه.", "فكذّبوه، فأخبر الله أنهم «لمحضرون» أي لمعذّبون، «إلا عباد الله المخلصين». وأبقى لإلياس ذكرًا حسنًا في الأمم بعده: «وتركنا عليه في الآخرين سلام على إل ياسين». وتذكر كتب التفسير أن إلياس كان في بني إسرائيل بعد موسى.", "وأما اليسع فقد ذكره الله في سورة الأنعام ضمن الأنبياء الذين فضّلهم: «وإسماعيل واليسع ويونس ولوطًا وكلًّا فضّلنا على العالمين». وفي سورة ص: «واذكر إسماعيل واليسع وذا الكفل وكلٌّ من الأخيار».", "وأما ذو الكفل فذكره الله في سورة الأنبياء ضمن الصابرين، وفي سورة ص ضمن الأخيار. ولم يذكر القرآن تفاصيل قصته، وللمفسرين في اسمه ونبوته أقوال، فنتوقف عند ما ذكره القرآن.", "وقال الله: «ورسلًا قد قصصناهم عليك من قبل ورسلًا لم نقصصهم عليك». فمن الأنبياء من لم يذكر الله لنا خبره، ونؤمن بالجميع دون تفريق."], "f": ["الإيمان بالأنبياء كلهم دون تفريق.", "دعوتهم واحدة: عبادة الله وحده."], "qs": [{"t": "fill", "q": "أتدعون ___ وتذرون أحسن الخالقين.", "c": "بعلًا", "w": ["وَدًّا", "هُبَل", "اللات"], "n": "قالها إلياس لقومه."}, {"t": "tf", "q": "ذكر القرآن قصص جميع الأنبياء بالتفصيل.", "c": false, "n": "منهم من لم يقصصهم الله علينا."}, {"t": "match", "q": "صِل كل نبي بما ذُكر عنه:", "pairs": [["إلياس", "دعا قومه عن عبادة بعل"], ["اليسع", "ذُكر في سورة الأنعام"], ["ذو الكفل", "من الصابرين والأخيار"], ["إدريس", "صدّيقًا نبيًّا"]], "n": "من آيات القرآن."}, {"q": "ماذا قال الله لإلياس وللأخيار في الآخرين؟", "c": "سلام على إل ياسين", "w": ["سلام على نوح", "سلام عليكم بما صبرتم", "سلام على إبراهيم"], "n": "أبقى الله له ذكرًا حسنًا."}, {"q": "أي سورة ذُكر فيها إلياس؟", "c": "الصافات", "w": ["مريم", "الأعراف", "هود"], "n": "وإن إلياس لمن المرسلين."}], "q": {"t": "fill", "q": "أتدعون ___ وتذرون أحسن الخالقين.", "c": "بعلًا", "w": ["وَدًّا", "هُبَل", "اللات"], "n": "قالها إلياس لقومه."}})})();
