  const XQ={"1": {"p": "وفي طفولته في بني سعد وقعت له حادثة شق الصدر: جاءه جبريل فشقّ صدره واستخرج منه حظّ الشيطان وغسله، كما ثبت في صحيح مسلم. وتروي كتب السيرة أن حليمة خافت عليه فأعادته إلى أمه.", "qs": [{"t": "tf", "q": "توفي أبو النبي ﷺ قبل ولادته.", "c": true, "n": "توفي عبد الله وآمنة حامل به."}, {"t": "ord", "q": "رتّب مراحل حياته المبكرة ﷺ:", "items": ["وُلد في مكة", "أُرضع في بني سعد", "توفيت أمه آمنة", "كفله جدّه عبد المطلب"], "n": "هكذا تتابعت المراحل الأولى من حياته."}]}, "2": {"p": "وكانت أحوال العرب في الجاهلية فيها خير وشر: كرم وشجاعة، لكن فيها عبادة الأصنام والظلم ووأد البنات. وكان النبي ﷺ بعيدًا عن ذلك، يحب الخلوة والتأمل.", "qs": [{"t": "tf", "q": "شارك النبي ﷺ قومه في عبادة الأصنام في شبابه.", "c": false, "n": "عُرف بنقاء فطرته وبُعده عن عبادة الأصنام."}, {"t": "ord", "q": "رتّب أحداث الحجر الأسود:", "items": ["تنازعت القبائل على شرف وضعه", "اتفقوا على تحكيم أول داخل", "وضع الحجر على ثوب وحملته القبائل", "وضعه ﷺ بيده في مكانه"], "n": "بحكمته جنّب مكة الخصام."}]}, "3": {"p": "وكان نزول الوحي في ليلة القدر من رمضان، قال تعالى: «إنا أنزلناه في ليلة القدر». وكان عمره ﷺ حينها نحو أربعين سنة.", "qs": [{"t": "tf", "q": "كان عمر النبي ﷺ عند نزول الوحي نحو أربعين سنة.", "c": true, "n": "بُعث ﷺ على رأس الأربعين."}, {"t": "fill", "q": "أول آية نزلت: «اقرأ باسم ___ الذي خلق».", "c": "ربّك", "w": ["الله", "الرحمن", "نبيّك"], "n": "أول ما نزل: اقرأ باسم ربك الذي خلق."}]}, "4": {"p": "وكان من أسباب إسلام الناس صدق النبي ﷺ وحسن خلقه، فكان الرجل يرى الإيمان في معاملته قبل أن يسمع كلامه. ولم يكن الأمر سهلًا، فقد آذتهم قريش وفتنتهم في دينهم.", "qs": [{"t": "tf", "q": "كانت الدعوة في بدايتها علنية أمام الجميع.", "c": false, "n": "كانت سرّية نحو ثلاث سنين."}, {"t": "match", "q": "صِل كل صحابي بما يناسبه:", "pairs": [["خديجة", "زوجة النبي ﷺ"], ["أبو بكر", "صاحبه في الغار"], ["علي", "ابن عمّه"], ["زيد بن حارثة", "مولاه الذي تبنّاه"]], "n": "هؤلاء من أوائل المؤمنين."}]}, "5": {"p": "ولم يتوقف الأذى، فقد وضعوا سلا الجزور على ظهره وهو ساجد عند الكعبة، فتحمّل صابرًا حتى أزالته عنه ابنته فاطمة رضي الله عنها.", "qs": [{"t": "tf", "q": "جهر النبي ﷺ بالدعوة مباشرة بعد نزول أول الوحي.", "c": false, "n": "سبقتها نحو ثلاث سنين من الدعوة السرّية."}, {"t": "fill", "q": "قال لهم: لو أخبرتكم أن ___ بسفح هذا الجبل تريد أن تغير عليكم.", "c": "خيلًا", "w": ["جيشًا من الروم", "سيلًا", "نارًا"], "n": "فصدّقوه لما عرفوا من صدقه."}]}, "6": {"p": "وعاد بعض المهاجرين من الحبشة إلى المدينة في السنة السابعة للهجرة. وتذكر كتب السيرة أن النبي ﷺ فرح بقدوم جعفر وقال: ما أدري بأيهما أنا أفرح: بفتح خيبر أم بقدوم جعفر.", "qs": [{"t": "tf", "q": "سلّم النجاشي المسلمين لوفد قريش.", "c": false, "n": "رفض النجاشي تسليمهم وحماهم."}, {"t": "ord", "q": "رتّب أحداث الهجرة إلى الحبشة:", "items": ["اشتدّ أذى قريش", "هاجر المسلمون إلى الحبشة", "أرسلت قريش وفدًا إلى النجاشي", "تكلّم جعفر ورفض النجاشي تسليمهم"], "n": "فكانت أول هجرة في الإسلام."}]}, "14": {"p": "وعُرف حمزة بعد ذلك بأسد الله وأسد رسوله، وشهد بدرًا وقاتل ببسالة حتى استُشهد في أُحد. أما عمر فصار من أقرب الصحابة إلى النبي ﷺ، وتزوّج النبي ﷺ ابنته حفصة.", "qs": [{"t": "tf", "q": "أسلم عمر بعد إسلام حمزة بأيام.", "c": true, "n": "تقارب إسلامهما وفرّح المسلمين."}, {"t": "match", "q": "صِل كل اسم بما يناسبه:", "pairs": [["حمزة", "أسد الله وأسد رسوله"], ["عمر", "الفاروق"], ["فاطمة بنت الخطاب", "أخت عمر المسلمة"], ["أبو جهل", "من آذى النبي ﷺ عند الصفا"]], "n": "ملخّص أشخاص القصة."}]}, "13": {"p": "وتذكر كتب السيرة أن أبا طالب كان ينقل النبي ﷺ من فراشه ليلًا ويُنيم مكانه أحد أبنائه، خوفًا من غدر قريش به.", "qs": [{"t": "tf", "q": "شمل المقاطعة منع البيع والشراء والزواج مع بني هاشم.", "c": true, "n": "كانت مقاطعة شاملة."}, {"t": "fill", "q": "سُمّي ذلك العام «عام ___».", "c": "الحزن", "w": ["الفيل", "الوفود", "الفتح"], "n": "لوفاة أبي طالب وخديجة."}]}, "15": {"p": "ولما عاد من الطائف نزل بنخلة وقرأ القرآن في صلاته، فسمعه نفر من الجن فآمنوا، وفيه نزلت سورة الجن. ثم دخل مكة في جوار المطعم بن عدي.", "qs": [{"t": "tf", "q": "رجع النبي ﷺ من الطائف بعد أن نصرته ثقيف.", "c": false, "n": "ردّوه ردًّا قبيحًا وآذوه."}, {"t": "ord", "q": "رتّب أحداث الطائف:", "items": ["وصل الطائف ودعا زعماءهم", "سلّطوا عليه السفهاء", "جلس في بستان يدعو ربه", "قدّم له عدّاس العنب"], "n": "ثم عاد إلى مكة صابرًا."}]}, "16": {"p": "وفي المعراج رأى النبي ﷺ من الآيات العظيمة، قال تعالى: «لقد رأى من آيات ربه الكبرى». وكان البراق دابة أبيض يضع حافره عند منتهى بصره.", "qs": [{"t": "tf", "q": "فُرضت الصلاة في ليلة الإسراء والمعراج.", "c": true, "n": "فُرضت خمسين ثم خُفّفت إلى خمس."}, {"t": "match", "q": "صِل المكان بما يناسبه:", "pairs": [["المسجد الحرام", "بداية الرحلة"], ["المسجد الأقصى", "صلّى فيه بالأنبياء"], ["سدرة المنتهى", "أعلى ما وصل إليه"], ["خمس صلوات", "ما استقرّ عليه الفرض"]], "n": "من أحداث الليلة المباركة."}]}, "7": {"p": "وجاء في العقبة الأولى اثنا عشر رجلًا فبايعوه على التوحيد وترك المعاصي، ثم جاء في الثانية ثلاثة وسبعون رجلًا وامرأتان فبايعوه على النصرة.", "qs": [{"t": "tf", "q": "بايع أهل المدينة النبي ﷺ على نصرته وحمايته.", "c": true, "n": "كما يحمون نساءهم وأبناءهم."}, {"t": "ord", "q": "رتّب أحداث بيعة العقبة:", "items": ["لقاء ستة من الخزرج", "بيعة العقبة الأولى", "إرسال مصعب إلى المدينة", "بيعة العقبة الثانية"], "n": "ثم تهيأت الهجرة."}]}, "8": {"p": "وكانت الهجرة في ربيع الأول، وهي حدث غيّر مجرى التاريخ، فانتقل الإسلام فيها من مرحلة الاستضعاف إلى بناء مجتمع ودولة.", "qs": [{"t": "tf", "q": "استأجر أبو بكر دليلًا مشركًا للطريق.", "c": true, "n": "استأجر عبد الله بن أريقط لأمانته ومعرفته بالطرق."}, {"t": "fill", "q": "«لا تحزن إن الله ___».", "c": "معنا", "w": ["ناصرنا", "قريب", "حافظنا"], "n": "معيّة الله تطمئن القلب."}]}, "9": {"p": "وكانت القبلة أول الأمر نحو بيت المقدس، ثم حُوّلت إلى الكعبة في السنة الثانية للهجرة، فصلّى المسلمون نحو المسجد الحرام.", "qs": [{"t": "tf", "q": "بُني المسجد النبوي بالحجارة المنحوتة والرخام.", "c": false, "n": "بُني باللبن وجذوع النخل."}, {"t": "match", "q": "صِل كل عنصر بما يناسبه:", "pairs": [["المهاجرون", "من جاؤوا من مكة"], ["الأنصار", "أهل المدينة المستقبلون"], ["أهل الصفة", "فقراء يسكنون المسجد"], ["بلال", "أول مؤذّن"]], "n": "من مكوّنات المجتمع الأول."}]}, "10": {"p": "ومن معالم المعركة أن النبي ﷺ نزل عند أدنى ماء بمشورة الحباب بن المنذر، فجعلوا الآبار خلفهم وحوضًا يشربون منه، وحرموا العدو من الماء.", "qs": [{"t": "tf", "q": "كان جيش قريش أقل عددًا من جيش المسلمين.", "c": false, "n": "كانوا نحو ألف مقابل ثلاثمئة وبضعة عشر."}, {"t": "ord", "q": "رتّب أحداث بدر:", "items": ["خرج المسلمون لقافلة أبي سفيان", "نجت القافلة وخرجت قريش بجيشها", "استشار النبي ﷺ أصحابه", "انتصر المسلمون في بدر"], "n": "كان نصرًا عظيمًا."}]}, "17": {"p": "وفي المعركة دافع طلحة وأبو دجانة وسعد وغيرهم عن النبي ﷺ دفاعًا عظيمًا، وحملت نسيبة بنت كعب (أم عمارة) السيف تدافع عنه.", "qs": [{"t": "tf", "q": "كان خالد بن الوليد في صفّ المسلمين يوم أُحد.", "c": false, "n": "كان يومئذ قائد فرسان قريش."}, {"t": "fill", "q": "أمرهم ألا يتركوا ___ ولو رأوا الطير تتخطف المسلمين.", "c": "مكانهم", "w": ["أسلحتهم", "خيولهم", "المدينة"], "n": "ترك الموقع غيّر نتيجة المعركة."}]}, "18": {"p": "ومن بركات الغزوة أن جابرًا صنع طعامًا يسيرًا من شاة وصاع شعير، فبارك النبي ﷺ فيه فأكل منه الجيش كله، كما في صحيح البخاري.", "qs": [{"t": "tf", "q": "كان حفر الخندق معروفًا عند العرب قبل ذلك.", "c": false, "n": "كانت فكرة جديدة من سلمان."}, {"t": "ord", "q": "رتّب أحداث الخندق:", "items": ["تجمّع الأحزاب حول المدينة", "اقترح سلمان حفر الخندق", "حاصر الأحزاب المدينة أيامًا", "أرسل الله ريحًا فانصرف الأحزاب"], "n": "ثم تغيّر ميزان القوة."}]}, "19": {"p": "وبعد الصلح أمر النبي ﷺ أصحابه أن ينحروا هديهم ويحلقوا، فتردّدوا حزنًا، فأشارت أم سلمة رضي الله عنها عليه أن يفعل ذلك أولًا بنفسه، ففعل فتبعه الناس.", "qs": [{"t": "tf", "q": "وافقت قريش على أن يعتمر المسلمون في العام نفسه.", "c": false, "n": "اتفقوا على العودة في العام القادم."}, {"t": "match", "q": "صِل كل عنصر بما يناسبه:", "pairs": [["بيعة الرضوان", "تحت الشجرة"], ["سهيل بن عمرو", "ممثل قريش في الصلح"], ["سورة الفتح", "نزلت بعد الصلح"], ["عشر سنين", "مدة وقف القتال"]], "n": "من أحداث الحديبية."}]}, "22": {"p": "وبعد المعركة جاء النبي ﷺ إلى أهل جعفر وقال: «اصنعوا لآل جعفر طعامًا فقد أتاهم ما يشغلهم»، كما في السنن.", "qs": [{"t": "tf", "q": "استُشهد القادة الثلاثة الذين عيّنهم النبي ﷺ في مؤتة.", "c": true, "n": "زيد ثم جعفر ثم ابن رواحة."}, {"t": "ord", "q": "رتّب القادة كما عيّنهم النبي ﷺ:", "items": ["زيد بن حارثة", "جعفر بن أبي طالب", "عبد الله بن رواحة", "خالد بن الوليد"], "n": "الرابع أخذ الراية بعد استشهادهم."}]}, "11": {"p": "ومن صور رحمته أنه أمر جيشه ألا يقاتلوا إلا من قاتلهم، وبقي في مكة نحو تسعة عشر يومًا يعلّم الناس ويصلح الأحوال ثم عاد إلى المدينة.", "qs": [{"t": "tf", "q": "انتقم النبي ﷺ من أهل مكة عند الفتح.", "c": false, "n": "عفا عنهم عفوًا عامًّا."}, {"t": "fill", "q": "قال لهم: اذهبوا فأنتم ___.", "c": "الطلقاء", "w": ["المهاجرون", "الأنصار", "الأحرار"], "n": "كان فتح رحمة وعفو."}]}, "20": {"p": "وبعد الغزوة حاصر المسلمون الطائف أيامًا ثم رجعوا، وجاء وفد ثقيف مسلمين في السنة التاسعة، فكان ذلك فتحًا للطائف بالسلم.", "qs": [{"t": "tf", "q": "كان جيش المسلمين في حنين أقل من ألف.", "c": false, "n": "كانوا نحو اثني عشر ألفًا."}, {"t": "match", "q": "صِل كل عنصر بما يناسبه:", "pairs": [["هوازن", "القبيلة المحاربة"], ["العباس", "من نادى المسلمين"], ["المؤلّفة قلوبهم", "من أُعطوا لتأليف قلوبهم"], ["اثنا عشر ألفًا", "عدد جيش المسلمين"]], "n": "من أحداث حنين."}]}, "21": {"p": "وفي الطريق مرّوا بديار ثمود، فأمرهم النبي ﷺ ألا يدخلوها إلا باكين معتبرين، كما في صحيح البخاري.", "qs": [{"t": "tf", "q": "خاض المسلمون في تبوك قتالًا كبيرًا مع الروم.", "c": false, "n": "لم يلقوا حربًا وعادوا."}, {"t": "ord", "q": "رتّب أحداث تبوك:", "items": ["بلغ المسلمين تجمّع الروم", "تسابق الصحابة إلى الإنفاق", "خرج الجيش إلى تبوك", "عاد النبي ﷺ إلى المدينة"], "n": "كانت آخر غزوة له ﷺ."}]}, "12": {"p": "ومن الخطبة قوله ﷺ: «إن دماءكم وأموالكم عليكم حرام كحرمة يومكم هذا في شهركم هذا في بلدكم هذا». ثم قال: «ألا هل بلّغت؟» فقالوا: نعم، فقال: «اللهم اشهد».", "qs": [{"t": "tf", "q": "حجّ النبي ﷺ أكثر من حجة بعد الهجرة.", "c": false, "n": "لم يحجّ بعد الهجرة إلا حجة الوداع."}, {"t": "fill", "q": "سُمّيت حجة ___ لأنه ودّع الناس فيها.", "c": "الوداع", "w": ["الفتح", "الرضوان", "العقبة"], "n": "كانت آخر حجة له ﷺ."}]}, "23": {"p": "ومن كلامه لما بُويع بالخلافة: «أيها الناس إني وُلّيت عليكم ولست بخيركم، فإن أحسنت فأعينوني وإن أسأت فقوّموني».", "qs": [{"t": "tf", "q": "أنفق أبو بكر ماله كله في جيش العسرة.", "c": true, "n": "جاء بماله كله فسأله النبي ﷺ: ما أبقيت لأهلك؟ قال: أبقيت لهم الله ورسوله."}, {"t": "fill", "q": "قال أبو بكر: أطيعوني ما أطعت ___ فيكم.", "c": "الله", "w": ["الناس", "قومي", "السلطان"], "n": "وكان يقول: فإن عصيته فلا طاعة لي عليكم."}]}, "24": {"p": "ويُروى عن عمر قوله: لو عثرت بغلة في العراق لخشيت أن يسألني الله عنها: لِمَ لم تُمهّد لها الطريق يا عمر؟ وهو يدل على شدة مسؤوليته عن الرعية.", "qs": [{"t": "tf", "q": "استُشهد عمر وهو يصلّي الفجر.", "c": true, "n": "طعنه أبو لؤلؤة المجوسي."}, {"t": "match", "q": "صِل كل صحابي بلقبه:", "pairs": [["أبو بكر", "الصدّيق"], ["عمر", "الفاروق"], ["عثمان", "ذو النورين"], ["خالد", "سيف الله"]], "n": "ألقاب مشهورة."}]}, "25": {"p": "وكان شديد الحياء، حتى قال النبي ﷺ: «ألا أستحيي من رجل تستحيي منه الملائكة؟»، رواه مسلم.", "qs": [{"t": "tf", "q": "كان عثمان أول خليفة بعد النبي ﷺ.", "c": false, "n": "كان أبو بكر أول الخلفاء."}, {"t": "ord", "q": "رتّب أعمال عثمان:", "items": ["هاجر إلى الحبشة", "هاجر إلى المدينة", "جهّز جيش العسرة", "جمع الناس على مصحف واحد"], "n": "من سيرته العطرة."}]}, "26": {"p": "وأوصاه النبي ﷺ في خيبر أن يدعو أهلها برفق، وقال: «فوالله لأن يهدي الله بك رجلًا واحدًا خير لك من حُمر النعم»، رواه البخاري ومسلم.", "qs": [{"t": "tf", "q": "تولّى علي الخلافة بعد عمر مباشرة.", "c": false, "n": "تولّى بعد عثمان رضي الله عنهم."}, {"t": "fill", "q": "استُشهد علي على يد ابن ___.", "c": "ملجم", "w": ["سلول", "العاص", "جهل"], "n": "وهو خارج لصلاة الفجر."}]}, "27": {"p": "وقال له النبي ﷺ: «يا بلال حدّثني بأرجى عمل عملته في الإسلام فإني سمعت دفّ نعليك بين يديّ في الجنة»، فقال: ما عملت عملًا أرجى عندي من أني لم أتطهّر طهورًا إلا صلّيت بعده ما كُتب لي. رواه البخاري.", "qs": [{"t": "tf", "q": "كان بلال أول مؤذّن في الإسلام.", "c": true, "n": "اختاره النبي ﷺ لحسن صوته."}, {"t": "ord", "q": "رتّب أحداث حياة بلال:", "items": ["عُذّب في مكة", "اشتراه أبو بكر وأعتقه", "أذّن في المدينة", "أذّن على الكعبة يوم الفتح"], "n": "من الاستضعاف إلى العزّة."}]}, "28": {"p": "وكان زاهدًا متواضعًا، فلما وُلّي المدائن كان يعيش من عمل يده ولم يغيّره المنصب.", "qs": [{"t": "tf", "q": "أسلم سلمان وهو في بلاد فارس.", "c": false, "n": "أسلم في المدينة بعد هجرة النبي ﷺ."}, {"t": "ord", "q": "رتّب رحلة سلمان:", "items": ["نشأ مجوسيًا في فارس", "اتّجه إلى النصرانية", "صار عبدًا في المدينة", "أسلم وشهد الخندق"], "n": "رحلة بحث عن الحق."}]}, "29": {"p": "وكان مصعب يدعو بالحسنى، فلما جاءه أسيد بن حضير غاضبًا قال له: اجلس فإن رضيت أمرًا قبلته وإن كرهته كُفّ عنك. فجلس واستمع فأسلم. وتروي ذلك كتب السيرة.", "qs": [{"t": "tf", "q": "استُشهد مصعب بن عمير في غزوة بدر.", "c": false, "n": "استُشهد في أُحد."}, {"t": "fill", "q": "كُفّن مصعب في بردة إذا غطّوا رأسه ظهرت ___.", "c": "رجلاه", "w": ["صدره", "كتفاه", "وجهه"], "n": "لم يترك من الدنيا شيئًا."}]}, "30": {"p": "وكان إذا قُدّم له طعام بكى وقال: قُتل مصعب بن عمير وهو خير مني فلم يوجد له ما يُكفَّن فيه إلا بردة، وخشي أن تكون طيّباته عُجّلت له. رواه البخاري.", "qs": [{"t": "tf", "q": "كان عبد الرحمن بن عوف من العشرة المبشّرين بالجنة.", "c": true, "n": "وهو من السابقين الأولين."}, {"t": "ord", "q": "رتّب سيرة عبد الرحمن:", "items": ["هاجر وترك ماله", "آخى النبي ﷺ بينه وبين سعد بن الربيع", "عمل بالتجارة حتى كثر ماله", "اختار عثمان للخلافة"], "n": "درس في العمل والإيثار."}]}, "31": {"p": "ومن مواقفها العلمية أنها كانت تناقش الصحابة وتستدرك عليهم في بعض ما فهموه، ولما نزلت آية التخيير اختارت الله ورسوله والدار الآخرة.", "qs": [{"t": "tf", "q": "دُفنت عائشة رضي الله عنها في البقيع.", "c": true, "n": "بالمدينة المنورة."}, {"t": "fill", "q": "توفي النبي ﷺ ودُفن في حجرة ___.", "c": "عائشة", "w": ["حفصة", "خديجة", "أم سلمة"], "n": "ثم دُفن أبو بكر وعمر بجواره."}]}, "32": {"p": "وكانت معركة اليرموك من أشهر معاركه، وأتقن فيها تعبئة الجيش، وانتصر المسلمون على الروم نصرًا كبيرًا مهّد لفتح الشام.", "qs": [{"t": "tf", "q": "أسلم خالد بن الوليد قبل غزوة أُحد.", "c": false, "n": "أسلم بعدها بسنوات قبل فتح مكة."}, {"t": "ord", "q": "رتّب سيرة خالد:", "items": ["قاد فرسان قريش في أُحد", "أسلم قبل فتح مكة", "أخذ الراية في مؤتة", "قاد المسلمين في اليرموك"], "n": "من الخصم إلى القائد."}]}};
  ST.forEach(function(x){const e=XQ[x.id];if(e){x.p.push(e.p);e.qs.forEach(function(q){x.qs.push(q)})}});
  const XP={"60": {"p": ["وقد أخبر النبي ﷺ أن الله خلق آدم من قبضة قبضها من جميع الأرض، فجاء بنو آدم على قدر الأرض: منهم الأحمر والأبيض والأسود، وبين ذلك السهل والحَزْن والخبيث والطيب. فكان الناس كلهم من أصل واحد.", "وكان وسوسة الشيطان بالوعد الكاذب، فقال: «هل أدلك على شجرة الخلد وملك لا يبلى»، وأقسم لهما «إني لكما لمن الناصحين». فعلّمنا القرآن ألّا نغترّ بمن يزيّن لنا الباطل بحجة النصح، وقال تعالى: «إن الشيطان لكم عدو فاتخذوه عدوًّا».", "وقال النبي ﷺ: «خير يوم طلعت عليه الشمس يوم الجمعة، فيه خُلق آدم، وفيه أُدخل الجنة، وفيه أُخرج منها». وقال: «كل ابن آدم خطّاء، وخير الخطّائين التوابون»، فالخطأ يقع من البشر، والمهم أن يرجع صاحبه بالتوبة."], "qs": [{"q": "في أي يوم خُلق آدم كما في الحديث الصحيح؟", "c": "يوم الجمعة", "w": ["يوم الاثنين", "يوم الخميس", "يوم السبت"], "n": "وفيه أُدخل الجنة وأُخرج منها."}, {"q": "بماذا أغرى الشيطان آدم؟", "c": "شجرة الخلد وملك لا يبلى", "w": ["بالمال والذهب", "بالمُلك على الجن", "بالعلم بالغيب"], "n": "وأقسم له أنه ناصح."}]}, "61": {"p": ["وكان من حجته على قومه أن قال لهم: «استغفروا ربكم إنه كان غفّارًا يرسل السماء عليكم مدرارًا ويمددكم بأموال وبنين ويجعل لكم جنات ويجعل لكم أنهارًا». فبيّن لهم أن الاستغفار يفتح أبواب الرزق.", "وبعد قرون من الدعوة أوحى الله إليه: «لن يؤمن من قومك إلا من قد آمن فلا تبتئس بما كانوا يفعلون». فدعا عليهم: «رب لا تذر على الأرض من الكافرين ديّارًا». ثم أمره الله بصنع السفينة.", "ولما ركبوا قال نوح: «بسم الله مجراها ومرساها إن ربي لغفور رحيم». وفي النهاية قال الله: «وقيل يا أرض ابلعي ماءك ويا سماء أقلعي وغيض الماء وقضي الأمر واستوت على الجودي».", "وقد وصفه الله بأنه «عبد شكور»، وجعل في ذريته النبوة والكتاب. وهو أول الرسل إلى أهل الأرض، وأحد أولي العزم من الرسل."], "qs": [{"t": "fill", "q": "بسم الله مجراها و___.", "c": "مرساها", "w": ["مسراها", "منشأها", "منتهاها"], "n": "قالها نوح عند ركوب السفينة."}, {"q": "ماذا وعد نوح قومه إن استغفروا؟", "c": "يرسل السماء عليهم مدرارًا ويمدّهم بالأموال والبنين", "w": ["أن يرفع عنهم الطوفان", "أن يجعلهم ملوكًا", "أن يخرجهم من الأرض"], "n": "استغفروا ربكم إنه كان غفّارًا."}]}, "62": {"p": ["وذكّرهم هود بنعم الله عليهم: «واذكروا إذ جعلكم خلفاء من بعد قوم نوح وزادكم في الخلق بسطة». وقال لهم: «أتبنون بكل ريع آية تعبثون وتتخذون مصانع لعلكم تخلدون»، فنهاهم عن العبث والغرور.", "وكانت حجتهم الاعتزاز بقوتهم، فقالوا: «من أشد منا قوة؟». فردّ الله عليهم: «أو لم يروا أن الله الذي خلقهم هو أشد منهم قوة».", "وكانت عائشة رضي الله عنها تروي أن النبي ﷺ كان إذا رأى غيمًا أو ريحًا عُرف في وجهه الخوف، وقال: «ما أدري لعله كما قال قوم هود: فلما رأوه عارضًا مستقبل أوديتهم قالوا هذا عارض ممطرنا». فكان يذكّر نفسه بعاقبة من عصى الله."], "qs": [{"t": "tf", "q": "كان النبي ﷺ إذا رأى الريح والغيم يخاف أن يكون عذابًا كما في قصة قوم هود.", "c": true, "n": "ورد ذلك في الحديث الصحيح."}, {"q": "بماذا اغترّ قوم عاد؟", "c": "بقوتهم", "w": ["بعلمهم", "بكثرة عددهم فقط", "بأرضهم الخصبة"], "n": "وقالوا: من أشد منا قوة؟"}]}, "63": {"p": ["وذكّرهم صالح بنعم الله: «واذكروا إذ جعلكم خلفاء من بعد عاد وبوّأكم في الأرض تتخذون من سهولها قصورًا وتنحتون الجبال بيوتًا». وكانت ديارهم في الحِجر بين الحجاز والشام.", "وانقسم قومه إلى طوائف: الذين استكبروا، والذين استُضعفوا، فسأل المستكبرون: «أتعلمون أن صالحًا مرسل من ربه؟» فقال المستضعفون: «إنا بما أُرسل به مؤمنون». فقال المستكبرون: «إنا بالذي آمنتم به كافرون».", "وقالوا لصالح: «اطّيّرنا بك وبمن معك»، أي تشاءمنا منك، فقال: «طائركم عند الله بل أنتم قوم تُفتنون». وبعد أن عقروا الناقة طلبوا العذاب: «يا صالح ائتنا بما تعدنا إن كنت من المرسلين»."], "qs": [{"t": "fill", "q": "وتنحتون الجبال ___.", "c": "بيوتًا", "w": ["قصورًا", "مصانع", "معابد"], "n": "قالها صالح يذكّرهم بنعم الله."}, {"q": "ماذا قال قوم صالح حين تشاءموا؟", "c": "اطّيّرنا بك وبمن معك", "w": ["أنت ساحر", "أنت مجنون", "أنت كاذب"], "n": "فردّ عليهم: طائركم عند الله."}]}, "64": {"p": ["ومن حواره مع الملك الذي كان يدّعي الربوبية: قال إبراهيم: «ربي الذي يحيي ويميت»، فقال الملك: «أنا أحيي وأميت». فقال إبراهيم: «فإن الله يأتي بالشمس من المشرق فأتِ بها من المغرب»، «فبُهت الذي كفر». وقد ذكر المفسرون أنه النمرود، ولم يُسمَّ في القرآن.", "وسأل إبراهيم ربه: «رب أرني كيف تحيي الموتى». قال: «أولم تؤمن؟» قال: «بلى ولكن ليطمئن قلبي». فأمره الله أن يأخذ أربعة من الطير فيقطّعهن، ثم يجعل على كل جبل منهن جزءًا، ثم يدعوهن، فيأتينه سعيًا.", "وجاءته الملائكة ضيوفًا في صورة رجال فأسرع وجاء بعجل حنيذ، فلما رأى أيديهم لا تصل إليه أنكرهم وأحسّ منهم خوفًا، فقالوا: «لا تخف إنا أُرسلنا إلى قوم لوط». ومنها يُتعلّم إكرام الضيف.", "ومن دعائه عند البيت: «ربّ اجعل هذا بلدًا آمنًا وارزق أهله من الثمرات»، فاستجاب الله دعاءه، فصار البلد آمنًا ويُجبى إليه ثمرات كل شيء. وقال الله: «واتخذ الله إبراهيم خليلًا»."], "qs": [{"t": "fill", "q": "بلى ولكن ليطمئن ___.", "c": "قلبي", "w": ["عقلي", "إيماني", "صدري"], "n": "قالها إبراهيم حين سأل عن إحياء الموتى."}, {"q": "ماذا فعل إبراهيم بالطيور الأربعة؟", "c": "قطّعهن ووضع على كل جبل جزءًا ثم دعاهن فأتينه سعيًا", "w": ["ربّاهن في بيته", "أطلقهن في السماء", "ذبحهن وأكلهن"], "n": "آية على إحياء الموتى."}]}, "65": {"p": ["ولما جاء قومه يهرعون إلى ضيوفه قال لوط ضيق الصدر: «لو أن لي بكم قوة أو آوي إلى ركن شديد». وقال النبي ﷺ: «يرحم الله لوطًا لقد كان يأوي إلى ركن شديد»، وهو الله سبحانه.", "فكشف الملائكة له الحقيقة وقالوا: «يا لوط إنا رسل ربك لن يصلوا إليك». وقالوا: «إن موعدهم الصبح أليس الصبح بقريب».", "فلما جاء أمر الله جعل عاليها سافلها وأمطر عليها حجارة من سجّيل منضود. وبقيت آثارهم عبرة، قال تعالى: «وإنكم لتمرّون عليهم مصبحين وبالليل أفلا تعقلون»."], "qs": [{"q": "ماذا قال النبي ﷺ عن لوط حين قال «أو آوي إلى ركن شديد»؟", "c": "كان يأوي إلى ركن شديد وهو الله", "w": ["كان ضعيفًا", "كان وحيدًا لا ناصر له", "كان خائفًا من الله"], "n": "من الحديث الصحيح."}, {"t": "tf", "q": "قال الملائكة للوط: إن موعدهم الصبح.", "c": true, "n": "أليس الصبح بقريب؟"}]}, "76": {"p": ["وقال النبي ﷺ عن ماء زمزم: «إنها مباركة، إنها طعام طُعْم». وكانت هاجر قد حبست الماء وقالت: «زمزم»، أي اجتمعي، ولذلك سُمّيت. وبقيت زمزم تسقي الحجاج حتى اليوم.", "وتروي كتب الحديث أن إبراهيم عاد بعد زمن يطمئن على أهله، فلم يجد إسماعيل، فسأل امرأته عن حاله فشكت ضيق العيش. فقال لها: «إذا جاء زوجك فأقرئي عليه السلام وقولي له يغيّر عتبة بابه». ففهم إسماعيل أنها الوصية بتطليقها.", "ثم تزوج إسماعيل أخرى، وجاء إبراهيم مرة ثانية فسأل زوجته، فحمدت الله وأثنت على العيش. فقال: «قولي له يثبّت عتبة بابه». وهي قصة تعلّمنا أن الزوجة الصالحة تحمد الله وتصبر.", "وكان إسماعيل ماهرًا في الرمي، وقال النبي ﷺ لقوم من أسلم يتناضلون بالسهام: «ارموا بني إسماعيل فإن أباكم كان راميًا»."], "qs": [{"q": "ماذا قال إبراهيم لزوجة إسماعيل في الزيارة الثانية؟", "c": "قولي له يثبّت عتبة بابه", "w": ["قولي له يغيّر عتبة بابه", "قولي له يرحل", "لا حاجة لي برسالة"], "n": "لأنها حمدت الله."}, {"t": "tf", "q": "قال النبي ﷺ: ارموا بني إسماعيل فإن أباكم كان راميًا.", "c": true, "n": "في الحديث الصحيح."}]}, "77": {"p": ["وأوصى يعقوب بنيه وهم ذاهبون إلى مصر: «يا بنيّ لا تدخلوا من باب واحد وادخلوا من أبواب متفرقة وما أُغني عنكم من الله من شيء». فأخذ بالأسباب مع التوكل على الله.", "ولما جاءه البشير بقميص يوسف قال: «إني لأجد ريح يوسف لولا أن تفنّدون»، أي تنسبونني إلى الخرف. فلما ألقى البشير القميص على وجهه ارتدّ بصيرًا، فقال لهم: «ألم أقل لكم إني أعلم من الله ما لا تعلمون؟».", "وحين اعترف أبناؤه بخطئهم وسألوه: «يا أبانا استغفر لنا ذنوبنا إنا كنا خاطئين»، قال: «سوف أستغفر لكم ربي إنه هو الغفور الرحيم». فعامل أبناءه بالرحمة."], "qs": [{"t": "fill", "q": "إني لأجد ريح ___ لولا أن تفنّدون.", "c": "يوسف", "w": ["أخي", "بنيامين", "أبي"], "n": "قالها يعقوب عند وصول القميص."}, {"q": "بماذا نصح يعقوب أبناءه عند دخول مصر؟", "c": "أن يدخلوا من أبواب متفرقة", "w": ["أن يدخلوا ليلًا", "أن يدخلوا مسلّحين", "أن يدخلوا متفرقين في أيام مختلفة"], "n": "مع بقاء التوكل على الله."}]}, "66": {"p": ["ولما رأت النسوة جمال يوسف قطّعن أيديهن، وقلن: «حاش لله ما هذا بشرًا إن هذا إلا ملك كريم». وقال يوسف في السجن داعيًا ربه: «رب السجن أحب إليّ مما يدعونني إليه وإلا تصرف عني كيدهنّ أصبُ إليهنّ وأكن من الجاهلين».", "وقال النبي ﷺ: «سبعة يظلّهم الله في ظلّه يوم لا ظلّ إلا ظله»، وذكر منهم: «ورجل دعته امرأة ذات منصب وجمال فقال: إني أخاف الله». وقال في يوسف: «الكريم ابن الكريم ابن الكريم ابن الكريم يوسف بن يعقوب بن إسحاق بن إبراهيم».", "وقال ﷺ عن صبر يوسف في السجن: «ولو لبثتُ في السجن ما لبث يوسف لأجبتُ الداعي»، أي أنه لم يستعجل الخروج بل أراد أن تُبرَّأ ساحته أولًا. فجاء تبرئته: «الآن حصحص الحق».", "ومن وصاياه لما تولّى: «اجعلني على خزائن الأرض إني حفيظ عليم»، فجمع بين الأمانة والعلم، وأدار الأزمة بحكمة فنجّى الناس من المجاعة."], "qs": [{"q": "ماذا قال النبي ﷺ عن يوسف وأبيه وجدّه؟", "c": "الكريم ابن الكريم ابن الكريم", "w": ["الصابر ابن الصابر", "النبي ابن النبي فقط", "العالم ابن العالم"], "n": "يوسف بن يعقوب بن إسحاق بن إبراهيم."}, {"t": "fill", "q": "رب السجن ___ إليّ مما يدعونني إليه.", "c": "أحب", "w": ["أبغض", "أهون", "أسهل"], "n": "قالها يوسف حين دُعي إلى الفاحشة."}]}, "67": {"p": ["وقال النبي ﷺ: «بينا أيوب يغتسل عريانًا خرّ عليه رجل جراد من ذهب، فجعل يحثي في ثوبه، فناداه ربه: يا أيوب ألم أكن أغنيتك عما ترى؟ قال: بلى يا رب، ولكن لا غنى لي عن بركتك». فبيّن أن الغنى الحقيقي بركة الله.", "وقال الله: «فاستجبنا له فكشفنا ما به من ضر وآتيناه أهله ومثلهم معهم رحمة من عندنا وذكرى للعابدين». فكان عاقبة صبره رحمة وذكرى لكل العابدين.", "وقال: «إنا وجدناه صابرًا نعم العبد إنه أوّاب». والأوّاب هو كثير الرجوع إلى الله."], "qs": [{"q": "ماذا قال أيوب حين سأله ربه ألم أكن أغنيتك؟", "c": "لا غنى لي عن بركتك", "w": ["بلى وكفى", "لا أريد المال", "اجعله لغيري"], "n": "في الحديث الصحيح."}, {"q": "ماذا تعني كلمة «أوّاب»؟", "c": "كثير الرجوع إلى الله", "w": ["كثير المال", "شديد القوة", "قليل الكلام"], "n": "وصف الله به أيوب."}]}, "68": {"p": ["وحذّرهم شعيب بمصير الأمم السابقة: «ويا قوم لا يجرمنّكم شقاقي أن يصيبكم مثل ما أصاب قوم نوح أو قوم هود أو قوم صالح وما قوم لوط منكم ببعيد». وقال: «واستغفروا ربكم ثم توبوا إليه إن ربي رحيم ودود».", "فردّوا عليه بغرور: «يا شعيب ما نفقه كثيرًا مما تقول وإنا لنراك فينا ضعيفًا ولولا رهطك لرجمناك وما أنت علينا بعزيز». فلم يزده ذلك إلا ثباتًا، وقال: «أرهطي أعزّ عليكم من الله؟».", "وأخيرًا دعا ربه: «ربنا افتح بيننا وبين قومنا بالحق وأنت خير الفاتحين». فجاء حكم الله بالرجفة."], "qs": [{"t": "fill", "q": "إن ربي رحيم ___.", "c": "ودود", "w": ["كريم", "غفور", "قريب"], "n": "من قول شعيب لقومه."}, {"q": "بماذا هدّد قوم شعيب نبيهم؟", "c": "بالرجم لولا رهطه", "w": ["بالنفي", "بالقتل بالسيف", "بالسجن"], "n": "فقال: أرهطي أعزّ عليكم من الله؟"}]}, "69": {"p": ["ولما قتل القبطي خطأً أدرك أنه وقع في ذنب، فقال: «رب إني ظلمت نفسي فاغفر لي فغفر له». وخرج من مصر «خائفًا يترقب». وفي مدين سقى للمرأتين ثم ظلّ فقيرًا فتوجّه إلى ربه: «رب إني لما أنزلت إليّ من خير فقير».", "فجاءته إحدى المرأتين تمشي على استحياء، وقالت: «إن أبي يدعوك ليجزيك أجر ما سقيت لنا». وقالت لأبيها: «يا أبتِ استأجره إن خير من استأجرت القوي الأمين». وقضى موسى عند الرجل الصالح أطول الأجلين، عشر سنين على ما روى البخاري.", "وحين كلّفه الله بالرسالة دعا: «ربّ اشرح لي صدري ويسّر لي أمري واحلل عقدة من لساني يفقهوا قولي». وهذا الدعاء من أحسن ما يُدعى به عند بدء الأعمال الكبيرة.", "وفي التيه أنزل الله على بني إسرائيل المنّ والسلوى، وفجّر لهم من الحجر اثنتي عشرة عينًا لكل سبط، وظلّلهم بالغمام. ومع ذلك طلبوا غير ذلك فقالوا: «لن نصبر على طعام واحد».", "ومن قصصه لقاؤه بعبد صالح ذكره القرآن في سورة الكهف، وسمّاه النبي ﷺ الخضر، فتعلّم أن علم الله أوسع من علم البشر."], "qs": [{"t": "fill", "q": "إن خير من استأجرت القوي ___.", "c": "الأمين", "w": ["الشجاع", "الحكيم", "الصادق"], "n": "قالتها ابنة الرجل الصالح."}, {"q": "كم سنة قضى موسى عند الرجل الصالح في مدين كما روى البخاري؟", "c": "عشر سنين", "w": ["ثماني سنين", "سنتين", "عشرين سنة"], "n": "قضى أكمل الأجلين."}]}, "78": {"p": ["ولهارون مكانة في الأمة: فقد قال النبي ﷺ لعلي رضي الله عنه حين استخلفه على المدينة في غزوة تبوك: «أنت مني بمنزلة هارون من موسى، إلا أنه لا نبي بعدي»، أي في الاستخلاف على الأهل.", "وتذكر كتب التفسير أن هارون توفي قبل موسى في التيه، ثم توفي موسى بعده. وبقي ذكرهما معًا في القرآن، حتى وُصفا بأنهما «من عبادنا المؤمنين»."], "qs": [{"q": "ماذا قال النبي ﷺ لعلي في غزوة تبوك؟", "c": "أنت مني بمنزلة هارون من موسى", "w": ["أنت أخي في الدين فقط", "أنت أفضل الصحابة", "أنت قائد جيشي"], "n": "إلا أنه لا نبي بعدي."}, {"t": "tf", "q": "توفي هارون قبل موسى عليهما السلام.", "c": true, "n": "على ما تذكر كتب التفسير."}]}, "70": {"p": ["وقال الله عن داود: «وشددنا ملكه وآتيناه الحكمة وفصل الخطاب»، أي القدرة على القضاء بين الناس. وكان يعيش على ما يصنع بيده، فيبيع الدروع ويأكل من ثمنها.", "وقال الله لآل داود: «اعملوا آل داود شكرًا»، فكان العمل بالشكر شعارهم. وقال النبي ﷺ: «أحب الصلاة إلى الله صلاة داود»، وكان ينام نصف الليل ويقوم ثلثه وينام سدسه.", "وبعد قصة الخصمين استغفر وخرّ راكعًا وأناب، فغفر الله له. وكانت قصته تذكيرًا بأن القاضي يحتاج إلى الصبر وسماع الخصمين."], "qs": [{"t": "fill", "q": "اعملوا آل داود ___.", "c": "شكرًا", "w": ["جهدًا", "صبرًا", "طاعة"], "n": "قالها الله لآل داود."}, {"q": "ما أحب الصلاة إلى الله كما قال النبي ﷺ؟", "c": "صلاة داود", "w": ["صلاة سليمان", "صلاة إبراهيم", "صلاة موسى"], "n": "ينام نصف الليل ويقوم ثلثه."}]}, "71": {"p": ["ومن آيات حكمته قضية الحرث: دخلت غنم قوم في زرع غيرهم ليلًا فأفسدته، فحكم داود بإعطاء الغنم لصاحب الزرع، فقال سليمان بحكم آخر أرفق بالطرفين. قال الله: «ففهمناها سليمان وكلًّا آتينا حكمًا وعلمًا». فأثنى الله عليهما معًا.", "ولما أُحضر عرش بلقيس قال الذي عنده علم من الكتاب: «أنا آتيك به قبل أن يرتدّ إليك طرفك». فلما رآه مستقرًّا عنده قال سليمان: «هذا من فضل ربي ليبلوني أأشكر أم أكفر».", "وقال النبي ﷺ إن سليمان قال: «لأطوفنّ الليلة على سبعين امرأة تلد كل واحدة غلامًا يقاتل في سبيل الله»، فلم يقل إن شاء الله، فلم تحمل منهن إلا واحدة جاءت بشقّ رجل. وفي ذلك درس بقول «إن شاء الله» وردّ الأمر إلى الله."], "qs": [{"t": "fill", "q": "هذا من فضل ربي ليبلوني أأشكر أم ___.", "c": "أكفر", "w": ["أنسى", "أعجز", "أضعف"], "n": "قالها سليمان لما رأى العرش."}, {"q": "ما الدرس من قول سليمان «لأطوفنّ…» ولم يقل إن شاء الله؟", "c": "أهمية قول إن شاء الله", "w": ["أن الأمور بيد البشر", "أن الملك لا يحتاج إلى مشيئة", "أن الأولاد زينة الدنيا"], "n": "في الحديث الصحيح."}]}, "72": {"p": ["وقوله تعالى: «فظنّ أن لن نقدر عليه» معناه عند المفسرين أنه ظن أن الله لن يضيّق عليه بسبب مغادرته. ثم تبيّن له خطأ اجتهاده في ترك قومه قبل أن يؤذن له.", "وقال النبي ﷺ: «لا ينبغي لعبد أن يقول إني خير من يونس بن متى»، ومعناه تعظيم مقام الأنبياء كلهم دون ازدراء أحد منهم. وسمّاه الله «ذا النون» أي صاحب الحوت.", "وقال النبي ﷺ عن دعاء ذي النون: «دعوة ذي النون إذ هو في بطن الحوت: لا إله إلا أنت سبحانك إني كنت من الظالمين، فإنه لم يدعُ بها رجل مسلم في شيء قط إلا استجاب الله له»."], "qs": [{"t": "tf", "q": "قال النبي ﷺ إن دعاء ذي النون لم يدعُ به مسلم في شيء إلا استجاب الله له.", "c": true, "n": "رواه الترمذي."}, {"q": "ماذا يعني «ذو النون»؟", "c": "صاحب الحوت", "w": ["صاحب النهر", "صاحب السفينة", "صاحب القرية"], "n": "لقب يونس في القرآن."}]}, "73": {"p": ["ووصف الله زكريا وزوجه ويحيى بقوله: «إنهم كانوا يسارعون في الخيرات ويدعوننا رغبًا ورهبًا وكانوا لنا خاشعين». فجمعوا بين الرجاء والخوف والخشوع.", "وبشّره الملائكة بيحيى في آية: «أن الله يبشّرك بيحيى مصدّقًا بكلمة من الله وسيدًا وحصورًا ونبيًّا من الصالحين»، والكلمة هنا عيسى. و«الحصور» هو الذي يعف نفسه عن الشهوات.", "وفي الحديث ثبت أن النبي ﷺ رأى يحيى وعيسى في السماء الثانية ليلة المعراج، وسلّم عليهما، فردّا السلام ورحّبا به."], "qs": [{"t": "fill", "q": "مصدّقًا بكلمة من الله وسيدًا و___.", "c": "حصورًا", "w": ["كريمًا", "شجاعًا", "زاهدًا"], "n": "وصف يحيى."}, {"q": "في أي سماء لقي النبي ﷺ يحيى وعيسى ليلة المعراج؟", "c": "الثانية", "w": ["الأولى", "الثالثة", "الرابعة"], "n": "كما في الصحيحين."}]}, "74": {"p": ["ومن آياته مائدة السماء: قال الحواريون: «هل يستطيع ربك أن ينزّل علينا مائدة من السماء». فقال عيسى: «اتقوا الله إن كنتم مؤمنين»، ثم دعا: «اللهم ربنا أنزل علينا مائدة من السماء تكون لنا عيدًا لأولنا وآخرنا». فأنزلها الله مع تحذير من الكفر بعدها.", "وبشّر عيسى ببعثة النبي ﷺ فقال: «يا بني إسرائيل إني رسول الله إليكم مصدّقًا لما بين يديّ من التوراة ومبشّرًا برسول يأتي من بعدي اسمه أحمد».", "وقال الله: «إن مثل عيسى عند الله كمثل آدم خلقه من تراب ثم قال له كن فيكون». فكما خُلق آدم بلا أب ولا أم، خُلق عيسى بلا أب. وكان يقول لقومه: «إن الله ربي وربكم فاعبدوه هذا صراط مستقيم»."], "qs": [{"t": "fill", "q": "ومبشّرًا برسول يأتي من بعدي اسمه ___.", "c": "أحمد", "w": ["محمد", "طه", "ياسين"], "n": "قالها عيسى لبني إسرائيل."}, {"q": "بمن شبّه الله خلق عيسى؟", "c": "آدم", "w": ["نوح", "موسى", "إبراهيم"], "n": "خلقه من تراب ثم قال له كن فيكون."}]}, "79": {"p": ["وأخذ الله من هؤلاء الرسل ميثاقًا غليظًا: «وإذ أخذنا من النبيين ميثاقهم ومنك ومن نوح وإبراهيم وموسى وعيسى ابن مريم وأخذنا منهم ميثاقًا غليظًا». فهم أعظم الرسل صبرًا وعزمًا.", "وفي حديث الشفاعة يوم القيامة، يأتي الناس آدم ثم نوحًا ثم إبراهيم ثم موسى ثم عيسى، فيعتذر كلٌّ منهم، حتى يأتوا محمدًا ﷺ فيقول: «أنا لها». وقال: «أنا سيد ولد آدم يوم القيامة ولا فخر»."], "qs": [{"t": "ord", "q": "في حديث الشفاعة، رتّب من يأتيهم الناس أولًا:", "items": ["آدم", "نوح", "إبراهيم", "موسى", "عيسى"], "n": "ثم يأتون محمدًا ﷺ فيشفع."}, {"q": "بماذا وصف الله الميثاق الذي أخذه من هؤلاء الرسل؟", "c": "ميثاقًا غليظًا", "w": ["ميثاقًا خفيفًا", "ميثاقًا مؤقتًا", "ميثاقًا عامًّا"], "n": "في سورة الأحزاب."}]}};
  ST.forEach(function(x){const e=XP[x.id];if(e){e.p.forEach(function(p){x.p.push(p)});e.qs.forEach(function(q){x.qs.push(q)})}});
