  function head(x,c,sub){return '<div class="sr-banner"><span class="big" aria-hidden="true">'+svg(SI[x.id]||c.ic,110)+'</span><span class="sr-badge">'+svg(c.ic,16)+esc(c.t)+'</span><h2>'+esc(x.t)+'</h2><div class="sr-meta">'+sub+'</div>'+(META[x.id]?'<div class="sr-chips"><span>'+svg('clock',15)+esc(META[x.id][0])+'</span><span>'+svg('pin',15)+esc(META[x.id][1])+'</span></div>':'')+'</div>'}
