  function stars(k){let h='<div class="sr-stars">';for(let i=0;i<3;i++)h+='<svg viewBox="0 0 24 24" width="46" height="46" fill="'+(i<k?'var(--gold)':'none')+'" stroke="'+(i<k?'var(--gold)':'var(--line)')+'" stroke-width="1.8" stroke-linejoin="round" aria-hidden="true" style="animation-delay:'+(i*.12)+'s">'+IC.star+'</svg>';return h+'</div>'}
