  function ansTxt(q){const t=q.t||'mc';return t==='tf'?(q.c?'صح':'خطأ'):t==='ord'?q.items.join(' ← '):t==='match'?q.pairs.map(function(z){return z[0]+' = '+z[1]}).join('، '):q.c}
  const QL={mc:'اختر الإجابة',fill:'أكمل الجملة',tf:'صح أم خطأ؟',ord:'رتّب الأحداث',match:'صِل كل عنصر بما يناسبه'};
